('e4bdce21-cdc6-5307-9c8d-8cff7a102d56', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Çiyayê Agirî li kîjan welatî ye?', 'Îran', 'Iraq', 'Tirkiye', 'Sûriye', 'C', 'Çiyayê Agirî, ango Ararat, li bakurê rojhilatê Tirkiyeyê ye û bilindtirîn çiyayê Tirkiyeyê ye.', 'Çiyayê Agirî, ango Ararat, li bakurê rojhilatê Tirkiyeyê ye û bilindtirîn çiyayê Tirkiyeyê ye.', 'Ağrı Dağı, yani Ararat, Türkiye''nin kuzeydoğusundadır ve Türkiye''nin en yüksek dağıdır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Mount_Ararat', NULL, 'https://en.wikipedia.org/wiki/Mount_Ararat', 'approved', 'Kurmancî', 1, now()),
('94fa5d13-39cb-5253-a58a-d783eafe00bc', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Kîjan çem di nav bajarê Amedê re derbas dibe?', 'Çemê Firatê', 'Çemê Muratê', 'Çemê Dîcleyê', 'Çemê Zapê', 'C', 'Çemê Dîcleyê di nav Amedê re derbas dibe û bajêr li ser perava wî hatiye avakirin.', 'Çemê Dîcleyê di nav Amedê re derbas dibe û bajêr li ser perava wî hatiye avakirin.', 'Dicle Nehri Diyarbakır''ın içinden geçer ve şehir onun kıyısında kurulmuştur.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Tigris', NULL, 'https://en.wikipedia.org/wiki/Tigris', 'approved', 'Kurmancî', 1, now()),
('401253f4-6fd8-5e94-b28d-f06b4f507d3e', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Kîjan çem di nav bajarê Mûsilê re derbas dibe?', 'Çemê Dîcleyê', 'Çemê Firatê', 'Çemê Zapê', 'Çemê Xabûrê', 'A', 'Çemê Dîcleyê di nav Mûsilê re derbas dibe û bajêr li ser perava wî hatiye avakirin.', 'Çemê Dîcleyê di nav Mûsilê re derbas dibe û bajêr li ser perava wî hatiye avakirin.', 'Dicle Nehri Musul''un içinden geçer ve şehir onun kıyısında kurulmuştur.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Tigris', NULL, 'https://en.wikipedia.org/wiki/Tigris', 'approved', 'Kurmancî', 1, now()),
('e5b6d674-beae-54a2-b071-f0b80c119199', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Kîjan çiyayê volkanîk li bakurê Kurdistanê ye û bi kratera xwe ya mezin tê naskirin?', 'Çiyayê Nemrûdê', 'Çiyayê Sîpanê Xelatê', 'Çiyayê Qendîlê', 'Çiyayê Cûdî', 'A', 'Volkana Nemrûdê li Bidlîsê, li derdora Tetwan û Xelatê ye.', 'Volkana Nemrûdê li Bidlîsê, li derdora Tetwan û Xelatê ye.', 'Nemrut volkanı Bitlis''te, Tatvan-Ahlat çevresindedir ve dünyanın en büyük krater göllerinden birini barındırır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Mount_Nemrut', NULL, 'https://en.wikipedia.org/wiki/Mount_Nemrut', 'approved', 'Kurmancî', 1, now()),
('aabec6d3-5f6b-50b3-8a8c-77b729ae6080', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Kîjan welat ji bo koçberên Kurdan yek ji armancên sereke bû di salên 1960î de?', 'Almanya', 'Fransa', 'Amerîka', 'Kanada', 'A', 'Di salên 1960î de gelek Kurd ji bo xebatê çûn Almanyayê wekî karkerên mêvan. Fransa, Amerîka û Kanada jî cihên koçberiyê ne lê Almanya ji bo Kurdan ya herî navdar e.', 'Di salên 1960î de gelek Kurd ji bo xebatê çûn Almanyayê wekî karkerên mêvan. Fransa, Amerîka û Kanada jî cihên koçberiyê ne lê Almanya ji bo Kurdan ya herî navdar e.', '1960''larda birçok Kürt, misafir işçi olarak çalışmak için Almanya''ya gitti. Fransa, Amerika ve Kanada da göç yerleridir, ancak Almanya Kürtler için en bilinenidir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurds_in_Germany', NULL, 'https://en.wikipedia.org/wiki/Kurds_in_Germany', 'approved', 'Kurmancî', 1, now()),
('72c86642-e5de-5827-ba64-d9c4ad598370', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Kîjan welat ji bo koçberên Kurdan di salên 1970î de bû armanca sereke?', 'Norwêc', 'Danîmarka', 'Swêd', 'Fînlandiya', 'C', 'Di salên 1970î de gelek Kurd ji bo penaberiyê çûn Swêdê. Swêd ji bo penaberên Kurdan bû welatekî navdar. Norwêc, Danîmarka û Fînlandiya jî cihên din in lê Swêd ya herî girîng e.', 'Di salên 1970î de gelek Kurd ji bo penaberiyê çûn Swêdê. Swêd ji bo penaberên Kurdan bû welatekî navdar. Norwêc, Danîmarka û Fînlandiya jî cihên din in lê Swêd ya herî girîng e.', '1970''li yıllarda birçok Kürt iltica etmek için İsveç''e gitmiştir. İsveç, Kürt mülteciler için ünlü bir ülke olmuştur. Norveç, Danimarka ve Finlandiya da diğer yerlerdir ancak en önemlisi İsveç''tir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurds_in_Sweden', NULL, 'https://en.wikipedia.org/wiki/Kurds_in_Sweden', 'approved', 'Kurmancî', 1, now()),
('af075713-3552-5cb7-b7be-85c03db21600', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Kîjan bajar paytextê herêma Kurdistanê ya Iraqê ye?', 'Hewlêr', 'Silêmanî', 'Kerkûk', 'Duhok', 'A', 'Hewlêr (Erbîl) paytextê Herêma Kurdistanê ya Iraqê ye. Silêmanî, Kerkûk û Duhok jî bajarên mezin in lê Hewlêr paytext e.', 'Hewlêr (Erbîl) paytextê Herêma Kurdistanê ya Iraqê ye. Silêmanî, Kerkûk û Duhok jî bajarên mezin in lê Hewlêr paytext e.', 'Erbil, Irak Kürdistan Bölgesi''nin başkentidir. Süleymaniye, Kerkük ve Duhok da büyük şehirlerdir ancak başkent Erbil''dir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Erbil', NULL, 'https://en.wikipedia.org/wiki/Erbil', 'approved', 'Kurmancî', 1, now()),
('a82a9ce4-99cb-5645-bee7-67d3ef15917a', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Kîjan çem di Hesîçeyê re derbas dibe û dikeve Firatê?', 'Çemê Xabûr', 'Çemê Balix', 'Çemê Ceyhan', 'Çemê Seyhan', 'A', 'Xabûrê Firatê di Hesîçeyê re derbas dibe û dikeve Firatê.', 'Xabûrê Firatê di Hesîçeyê re derbas dibe û dikeve Firatê.', 'Xabûrê Firatê, Haseke''den geçer ve Fırat''a katılır. Balix da Fırat''a dökülür ama Haseke''den geçmez.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Khabur_(Euphrates)', NULL, 'https://en.wikipedia.org/wiki/Khabur_(Euphrates)', 'approved', 'Kurmancî', 1, now()),
('3e271cac-6d79-52dd-b28e-3ce01bd2e8c4', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Kîjan bendav li ser Dîcleyê ye û li Bakurê Kurdistanê ye?', 'Bendava Keban', 'Bendava Karakaya', 'Bendava Ataturk', 'Bendava Ilisu', 'D', 'Bendava Ilisu li ser Dîcleyê ye û li Bakurê Kurdistanê ye. Bendava Keban û Karakaya li ser Firatê ne.', 'Bendava Ilisu li ser Dîcleyê ye û li Bakurê Kurdistanê ye. Bendava Keban û Karakaya li ser Firatê ne.', 'Ilısu Barajı Dicle üzerindedir ve Kuzey Kürdistan''dadır. Keban ve Karakaya barajları Fırat üzerindedir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Ilısu_Dam', NULL, 'https://en.wikipedia.org/wiki/Ilısu_Dam', 'approved', 'Kurmancî', 1, now()),
('e89f592d-e273-5777-a4f5-1ac0c9c5c1d6', (select id from categories where name = 'Cografya'), 'ku-kmr', 'Bendava Kralkizi li ser kîjan çemî hatiye avakirin?', 'Çemê Zapê', 'Çemê Madenê', 'Çemê Batmanê', 'Çemê Xabûrê', 'B', 'Bendava Kralkizi li ser Çemê Madenê yê hewza Dîcleyê hatiye avakirin.', 'Bendava Kralkizi li ser Çemê Madenê yê hewza Dîcleyê hatiye avakirin.', 'Kralkızı Barajı, Dicle havzasındaki Maden Çayı üzerinde kurulmuştur.', 3, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kralkızı_Dam', NULL, 'https://en.wikipedia.org/wiki/Kralkızı_Dam', 'approved', 'Kurmancî', 1, now()),
('79f19ac0-a71e-57e8-ae8a-25c5261761ec', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Şerefxanê Bidlîsî li ku derê hatiye dinyayê?', 'Bidlîs', 'Karahrûd (nêzî Qumê)', 'Cizîra Botan', 'Hekarî', 'B', 'Şerefxanê Bidlîsî di 1543an de li Karahrûda nêzî Qumê hat dinyayê; ji malbata mîrên Bidlîsê bû û navê xwe ji wê mîrektiyê digire.', 'Şerefxanê Bidlîsî di 1543an de li Karahrûda nêzî Qumê hat dinyayê; ji malbata mîrên Bidlîsê bû û navê xwe ji wê mîrektiyê digire.', 'Şerefhan Bitlisi 1543''te Kum yakınlarındaki Karahrud''da doğdu; Bitlis beyleri ailesindendi ve adını o beylikten alır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Sharafkhan_Bidlisi', NULL, 'https://en.wikipedia.org/wiki/Sharafkhan_Bidlisi', 'approved', 'Kurmancî', 1, now()),
('6282fdc4-4dea-59b0-bff9-9642487cb765', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Şerefxanê Bidlîsî ji kîjan dînî bû?', 'Şîa', 'Elewî', 'Sunnî', 'Yarsan', 'C', 'Şerefxanê Bidlîsî misilmanekî sunnî bû. Ew di pirtûka xwe de behsa dîn û baweriya kurdan jî dike.', 'Şerefxanê Bidlîsî misilmanekî sunnî bû. Ew di pirtûka xwe de behsa dîn û baweriya kurdan jî dike.', 'Şerefhan Bitlisi Sünni bir Müslümandı. Kitabında Kürtlerin din ve inancından da bahseder.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Sharafkhan_Bidlisi', NULL, 'https://en.wikipedia.org/wiki/Sharafkhan_Bidlisi', 'approved', 'Kurmancî', 1, now()),
('71a2e5ca-eda4-5b4f-86f6-184bc7f6152b', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Encama jeopolîtîk a herî sereke ya Peymana Qesrî Şîrîn (1639) li ser mîrektiyên kurd çi bû?', 'Hilweşîna yekcarî ya hemû mîrektiyan û derketina komaran', 'Parvekirina fermî ya Kurdistanê di navbera Osmanî û Sefewiyan de', 'Avakirina yekîtiyeke serbixwe ya mîran li tevahiya herêmê', 'Qedexekirina bazirganiya hevrîşimê li seranserê Rojhilata Navîn', 'B', 'Peymana Qesrî Şîrîn di sala 1639an de sînorê fermî yê di navbera Împaratoriya Osmanî û ya Sefewî de diyar kir û erdnîgariya kurdan kir du parçe.', 'Peymana Qesrî Şîrîn di sala 1639an de sînorê fermî yê di navbera Împaratoriya Osmanî û ya Sefewî de diyar kir û erdnîgariya kurdan kir du parçe.', 'Kasr-ı Şirin Antlaşması ile Osmanlı ve Safeviler arasındaki sınır resmileşmiş ve bölge ilk kez iki imparatorluk arasında bölünmüştür.', 5, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Sharafkhan_Bidlisi', NULL, 'https://en.wikipedia.org/wiki/Sharafkhan_Bidlisi', 'approved', 'Kurmancî', 1, now()),
('effe3c40-c159-5f52-9b51-cb40a1a8a87a', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Şerefxanê Bidlîsî di dawiya jiyana xwe de di xizmeta kîjan dewletê de bû?', 'Împaratoriya Sefewî', 'Împaratoriya Memlûkan', 'Împaratoriya Osmanî', 'Împaratoriya Bîzansê', 'C', 'Şerefxan pêşî li seraya Sefewiyan mezin bû, paşê derbasî aliyê Osmaniyan bû û wek mîrê Bidlîsê Şerefname li wir nivîsand.', 'Şerefxan pêşî li seraya Sefewiyan mezin bû, paşê derbasî aliyê Osmaniyan bû û wek mîrê Bidlîsê Şerefname li wir nivîsand.', 'Şerefhan önce Safevî sarayında yetişti, sonra Osmanlı tarafına geçti ve Bitlis beyi olarak Şerefname''yi orada yazdı.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Sharafkhan_Bidlisi', NULL, 'https://en.wikipedia.org/wiki/Sharafkhan_Bidlisi', 'approved', 'Kurmancî', 1, now()),
('3fb33d59-a62e-533a-bd1e-a905a8f785cc', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Şerefxanê Bidlîsî bi texmînî di kîjan salê de wefat kiriye?', '1603', '1613', '1623', '1633', 'A', 'Mirina Şerefxanê Bidlîsî di çavkaniyan de wek 1603-04 tê dayîn.', 'Mirina Şerefxanê Bidlîsî di çavkaniyan de wek 1603-04 tê dayîn.', 'Şerefxanê Bidlîsî''nin ölümü kaynaklarda 1603-04 olarak verilir; Şerefname''yi 1597''de tamamlamıştı.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Sharafkhan_Bidlisi', NULL, 'https://en.wikipedia.org/wiki/Sharafkhan_Bidlisi', 'approved', 'Kurmancî', 1, now()),
('f110b63a-6fa6-55d9-875a-309e44f9fe5b', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Şerefxanê Bidlîsî ji bo kîjan dewletê xebitiye?', 'Her du dewletan', 'Împaratoriya Osmanî', 'Împaratoriya Sefewî', 'Ti dewletê', 'A', 'Şerefxanê Bidlîsî ji bo her du dewletan, Împaratoriya Osmanî û Împaratoriya Sefewî, xebitiye. Ew di navbera her du dewletan de manevra kiriye.', 'Şerefxanê Bidlîsî ji bo her du dewletan, Împaratoriya Osmanî û Împaratoriya Sefewî, xebitiye. Ew di navbera her du dewletan de manevra kiriye.', 'Şerefxanê Bidlîsî, hem Osmanlı İmparatorluğu hem de Safevi İmparatorluğu için çalışmıştır. İki devlet arasında manevra yapmıştır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Sharafkhan_Bidlisi', NULL, 'https://en.wikipedia.org/wiki/Sharafkhan_Bidlisi', 'approved', 'Kurmancî', 1, now()),
('5c7bc4bd-e9e5-5a33-8651-1cd49db2798a', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Kovara Hawarê belavbûna kîjan alfabeyê pêş xist?', 'Alfabeya erebî', 'Alfabeya krîlî', 'Alfabeya aramî', 'Alfabeya latînî', 'D', 'Hawar di 1932yan de li Şamê derket û di bicihbûna alfabeya latînî ya kurmancî ya Celadet Bedirxan de roleke diyarker lîst.', 'Hawar di 1932yan de li Şamê derket û di bicihbûna alfabeya latînî ya kurmancî ya Celadet Bedirxan de roleke diyarker lîst.', 'Hawar 1932''de Şam''da çıktı ve Celadet Bedirxan''ın hazırladığı Latin esaslı Kurmancî alfabesinin yerleşmesinde belirleyici oldu. 1932''den önce de Kürtçe süreli yayınlar vardı.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Hawar_(magazine)', NULL, 'https://en.wikipedia.org/wiki/Hawar_(magazine)', 'approved', 'Kurmancî', 1, now()),
('507d9b7c-e812-5500-b56e-6bd0c914a78e', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Sedema sereke ya ku kovara "Hawar" (1932) li Şamê derket û ne li Stenbol an Amedê çi bû?', 'Rewşa siyasî ya piştî 1925an û qedexekirina rêxistin û weşanên kurdî li Tirkiyeyê', 'Li Şamê di 1923an de vekirina zankoyeke fîlolojiya rojhilatî', 'Daxwaza Fransiyan ji bo damezrandina radyoyeke erebî di 1930an de', 'Nebûna makîneyên çapxaneyê li bajarên herêmê beriya 1932an', 'A', 'Piştî Şoreşa Şêx Seîd zextên li ser ziman û çandê zêde bûn; malbata Bedirxaniyan li bin mandateriya Fransayê li Sûriyê xebatên çandî domandin.', 'Piştî Şoreşa Şêx Seîd zextên li ser ziman û çandê zêde bûn; malbata Bedirxaniyan li bin mandateriya Fransayê li Sûriyê xebatên çandî domandin.', '1925 sonrası yasaklamalar nedeniyle aydınlar Suriye mandasına geçmiş ve Hawar dergisi Şam''da Latin alfabesiyle yayımlanmıştır.', 4, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Hawar_(magazine)', NULL, 'https://en.wikipedia.org/wiki/Hawar_(magazine)', 'approved', 'Kurmancî', 1, now()),
('729e4073-06f5-56b3-8c06-5a10adb6f4f0', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Hawar ji bilî kovarê, di warê çi de jî girîng bû?', 'Çandina genim', 'Avakirina rêyan', 'Alfabeya Kurdî', 'Çêkirina çekan', 'C', 'Hawar ji bo pejirandina alfabeya Latînî ya Kurdî ya ku Celadet Alî Bedirxan pêşve bir, roleke bingehîn lîst. Kovar vê alfabeyê belav kir.', 'Hawar ji bo pejirandina alfabeya Latînî ya Kurdî ya ku Celadet Alî Bedirxan pêşve bir, roleke bingehîn lîst. Kovar vê alfabeyê belav kir.', 'Hawar, Celadet Alî Bedirxan''ın geliştirdiği Latin Kürt alfabesinin kabulünde temel bir rol oynadı. Dergi bu alfabeyi yaydı.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Hawar_(magazine)', NULL, 'https://en.wikipedia.org/wiki/Hawar_(magazine)', 'approved', 'Kurmancî', 1, now()),
('65b2d870-9c48-547f-96ce-63c3415d1b58', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Piştî hilweşandina Mîrektiya Botan a Bedirxan Paşa (1847) di civaka kurd de kîjan guherîna desthilatê çêbû?', 'Hemû herêm rasterast bêyî pirsgirêk kete bin sîstema nûjen a parlamenê', 'Mîrektiyên nû yên mezin li Şam û Helebê hatin avakirin', 'Zimanê kurdî di saziyên fermî de wekî zimanê yekem hate pejirandin', 'Desthilata mîran lawaz bû û şêxên terîqetan di qada civakî de derketin pêş', 'D', 'Bi polîtîkaya navendîbûnê ya Osmaniyan mîrektî hatin rakirin; valahiya desthilatê ji aliyê şêx û rêberên dînî ve hate tijîkirin.', 'Bi polîtîkaya navendîbûnê ya Osmaniyan mîrektî hatin rakirin; valahiya desthilatê ji aliyê şêx û rêberên dînî ve hate tijîkirin.', 'Osmanlı''nın merkezileşme politikasıyla mîrlikler tasfiye edilince doğan otorite boşluğunu şeyhler ve dini liderler doldurmuştur.', 5, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Bedir_Khan_Beg', NULL, 'https://en.wikipedia.org/wiki/Bedir_Khan_Beg', 'approved', 'Kurmancî', 1, now()),
('8ffc28fb-cb1f-5a1c-b6cc-96571c473c44', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Celadet Alî Bedirxan xebata rêzimana kurmancî bi kê re amade kir?', 'Vladimir Minorsky', 'Basil Nikitin', 'Roger Lescot', 'Thomas Bois', 'C', 'Celadet Alî Bedirxan rêzimana kurmancî bi rojhilatnasê fransî Roger Lescot re amade kir.', 'Celadet Alî Bedirxan rêzimana kurmancî bi rojhilatnasê fransî Roger Lescot re amade kir.', 'Celadet Alî Bedirxan, Kurmancî grameri Fransız şarkiyatçı Roger Lescot ile birlikte hazırladı.', 3, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Roger_Lescot', NULL, 'https://en.wikipedia.org/wiki/Roger_Lescot', 'approved', 'Kurmancî', 1, now()),
('dfa2b079-009b-5fd4-ba6d-fa75b464dd41', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Hawar çi cure kovar bû?', 'Kovara zanistî', 'Kovara edebî û çandî', 'Kovara sporê', 'Kovara aborî', 'B', 'Hawar kovara edebî û çandî bû ku di nav de helbest, çîrok, gotar û lêkolînên li ser ziman û çanda Kurdî dihatin weşandin.', 'Hawar kovara edebî û çandî bû ku di nav de helbest, çîrok, gotar û lêkolînên li ser ziman û çanda Kurdî dihatin weşandin.', 'Hawar, içinde şiir, öykü, makale ve Kürt dili ile kültürü üzerine araştırmaların yayımlandığı edebi ve kültürel bir dergiydi.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Hawar_(magazine)', NULL, 'https://en.wikipedia.org/wiki/Hawar_(magazine)', 'approved', 'Kurmancî', 1, now()),
('b7d06113-102a-553b-a594-1d4cd1a0e12b', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Bedirxan Paşa bi kîjan navî jî tê zanîn?', 'Mîr Bedir', 'Xan Bedir', 'Bedirxan Beg', 'Begê Bedir', 'C', 'Bedirxan Paşa bi navê Bedirxan Beg jî tê zanîn. Ew serokê mîrektiya Cizîrê bû û bi navê xwe yê tirkî yê osmanî jî dihat nasîn.', 'Bedirxan Paşa bi navê Bedirxan Beg jî tê zanîn. Ew serokê mîrektiya Cizîrê bû û bi navê xwe yê tirkî yê osmanî jî dihat nasîn.', 'Bedirxan Paşa, Bedirxan Beg adıyla da bilinir. Cizre Beyliği''nin lideriydi ve Osmanlı Türkçesi adıyla da tanınırdı.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Bedir_Khan_Beg', NULL, 'https://en.wikipedia.org/wiki/Bedir_Khan_Beg', 'approved', 'Kurmancî', 1, now()),
('71e4535a-d2f4-5126-bc27-73a7ff63b581', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Bedirxan Paşa li dijî kîjan dewletê serhildan kir?', 'Împaratoriya Farisî', 'Împaratoriya Rûsî', 'Împaratoriya Osmanî', 'Împaratoriya Brîtanî', 'C', 'Bedirxan Paşa di salên 1840î de li dijî Împaratoriya Osmanî serhildan kir. Ew dixwest mîrektiya xwe ya Cizîrê biparêze.', 'Bedirxan Paşa di salên 1840î de li dijî Împaratoriya Osmanî serhildan kir. Ew dixwest mîrektiya xwe ya Cizîrê biparêze.', 'Bedirhan Paşa 1840''lı yıllarda Osmanlı İmparatorluğu''na karşı isyan etti. Cizre''deki beyliğini korumak istiyordu.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Bedir_Khan_Beg', NULL, 'https://en.wikipedia.org/wiki/Bedir_Khan_Beg', 'approved', 'Kurmancî', 1, now()),
('fabfe9ba-7d82-5f8c-a144-bbace9e49090', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Hawar ji bo kîjan alfabeyê wek çavkaniya sereke tê zanîn?', 'Alfabeya Erebî ya Kurdî', 'Alfabeya Latînî ya Kurdî', 'Alfabeya Kirîlî ya Kurdî', 'Alfabeya Tirkî', 'B', 'Hawar ji bo belavkirina alfabeya Latînî ya Kurdî wek çavkaniya sereke tê zanîn. Ev alfabe ji aliyê Celadet Alî Bedirxan ve hate pêşve xistin.', 'Hawar ji bo belavkirina alfabeya Latînî ya Kurdî wek çavkaniya sereke tê zanîn. Ev alfabe ji aliyê Celadet Alî Bedirxan ve hate pêşve xistin.', 'Hawar, Kürtçe Latin alfabesinin yayılması için ana kaynak olarak bilinir. Bu alfabe Celadet Ali Bedirhan tarafından geliştirilmiştir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Hawar_(magazine)', NULL, 'https://en.wikipedia.org/wiki/Hawar_(magazine)', 'approved', 'Kurmancî', 1, now()),
('b2a5eff1-883f-5cca-808d-0817b97ca3fd', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Kîjan bajarê Medan wekî paytexta wan dihat zanîn?', 'Babilon', 'Ekbatan', 'Nînova', 'Persepolis', 'B', 'Ekbatan, ango Hemedana îro, paytexta Medan bû û ji aliyê dîroknasan ve wekî navenda siyasî ya wan tê nasîn.', 'Ekbatan, ango Hemedana îro, paytexta Medan bû û ji aliyê dîroknasan ve wekî navenda siyasî ya wan tê nasîn.', 'Ekbatan, yani günümüzdeki Hemedan, Medlerin başkentiydi ve tarihçiler tarafından onların siyasi merkezi olarak kabul edilir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Ecbatana', NULL, 'https://en.wikipedia.org/wiki/Ecbatana', 'approved', 'Kurmancî', 1, now()),
('6299017c-f2e2-5ee6-a7b9-9f092ddad058', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Kîjan împaratorî piştî hilweşandina Medan li herêmê derket holê?', 'Împaratoriya Seleukî', 'Împaratoriya Efxanî', 'Împaratoriya Sasaniyan', 'Împaratoriya Hexamenişî', 'D', 'Kyros Astyages têk bir û serdestiya Medan bi dawî kir. Kyros û Kiyaksar du serwerên cuda ne.', 'Kyros Astyages têk bir û serdestiya Medan bi dawî kir. Kyros û Kiyaksar du serwerên cuda ne.', 'Kyros, Astyages''i yenerek Med egemenliğine son verdi ve Ahameniş İmparatorluğu''nu kurdu. Kyros (Keyhüsrev) ile Kiyaksar ayrı hükümdarlardır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Achaemenid_Empire', NULL, 'https://en.wikipedia.org/wiki/Achaemenid_Empire', 'approved', 'Kurmancî', 1, now()),
('47f39bae-667c-562f-96de-023b828b7f4b', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Bedirxan Paşa di bin desthilatdariya kîjan dewletê de bû?', 'Împaratoriya Sefewî', 'Împaratoriya Qacar', 'Împaratoriya Rûsî', 'Împaratoriya Osmanî', 'D', 'Bedirxan Paşa, mîrê Botanê, di bin desthilatdariya Împaratoriya Osmanî de bû, her çend ew bi awayekî nîvserbixwe hukum dikir.', 'Bedirxan Paşa, mîrê Botanê, di bin desthilatdariya Împaratoriya Osmanî de bû, her çend ew bi awayekî nîvserbixwe hukum dikir.', 'Botan Emiri Bedirhan Paşa, yarı özerk bir şekilde yönetmesine rağmen Osmanlı İmparatorluğu''nun egemenliği altındaydı.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Bedir_Khan_Beg', NULL, 'https://en.wikipedia.org/wiki/Bedir_Khan_Beg', 'approved', 'Kurmancî', 1, now()),
('a914f88e-6424-555a-b6d8-0f138117085e', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Kîjan mîrê Botanê bi navê Mîrê Cizîrê jî tê zanîn?', 'Mîr Mihemed', 'Şerefxanê Bidlîsî', 'Bedirxan Paşa', 'Xanê Lepzêrîn', 'C', 'Bedirxan Paşa, mîrê Botanê, bi navê Mîrê Cizîrê jî tê zanîn, ji ber ku paytexta wî bajarê Cizîrê bû.', 'Bedirxan Paşa, mîrê Botanê, bi navê Mîrê Cizîrê jî tê zanîn, ji ber ku paytexta wî bajarê Cizîrê bû.', 'Botan Emiri Bedirhan Paşa, başkenti Cizre şehri olduğu için Cizre Emiri olarak da bilinir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Bedir_Khan_Beg', NULL, 'https://en.wikipedia.org/wiki/Bedir_Khan_Beg', 'approved', 'Kurmancî', 1, now()),
('deed1880-227b-504f-aff4-263d1a6a895c', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Rojnameya Kurdistanê bi kîjan zaravayê kurdî derdiket?', 'Tirkî', 'Kurmancî', 'Erebî', 'Farisî', 'B', 'Rojnameya Kurdistanê bi kurmancî derdiket; di 31 hejmarên xwe de tirkiya osmanî jî hat bikaranîn.', 'Rojnameya Kurdistanê bi kurmancî derdiket; di 31 hejmarên xwe de tirkiya osmanî jî hat bikaranîn.', 'Kurdistan gazetesi Kurmancî yayımlandı; 31 sayılık yayın hayatında Osmanlı Türkçesi de kullanıldı.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdistan_(newspaper)', NULL, 'https://en.wikipedia.org/wiki/Kurdistan_(newspaper)', 'approved', 'Kurmancî', 1, now()),
('059a4f94-2004-5735-ac74-ae9963332955', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Hejmara yekem a rojnameya Kurdistanê li kîjan bajarî hat çapkirin?', 'Stenbol', 'Qahîre', 'Şam', 'Cenevre', 'B', 'Hejmara yekem a rojnameya Kurdistanê di 1898an de li Qahîreyê hat çapkirin.', 'Hejmara yekem a rojnameya Kurdistanê di 1898an de li Qahîreyê hat çapkirin.', 'Kurdistan gazetesinin ilk sayısı 1898''de Kahire''de basıldı; sonraki sayılar Cenevre, Londra ve Folkestone gibi merkezlere taşındı.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdistan_(newspaper)', NULL, 'https://en.wikipedia.org/wiki/Kurdistan_(newspaper)', 'approved', 'Kurmancî', 1, now()),
('ab3f32c1-6407-5173-9a97-db330b0e4f6a', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Rojnameya Kurdistanê li kîjan bajaran hat weşandin?', 'Stenbol, Îzmîr û Bursa', 'Tehran, Bexda û Şam', 'Moskova, Erîvan û Tiflîs', 'Qahîre, Cenevre û London', 'D', 'Rojnameya Kurdistanê di 1898an de li Qahîreyê dest pê kir, paşê li Cenevre, London û Folkestone derket.', 'Rojnameya Kurdistanê di 1898an de li Qahîreyê dest pê kir, paşê li Cenevre, London û Folkestone derket.', 'Kurdistan gazetesi 1898''de Kahire''de başladı; sonra Cenevre, Londra ve Folkestone gibi merkezlerde çıkarıldı.', 3, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdistan_(newspaper)', NULL, 'https://en.wikipedia.org/wiki/Kurdistan_(newspaper)', 'approved', 'Kurmancî', 1, now()),
('c5eb7ffc-9d1a-5b47-8080-f570a9dcde6f', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Hejmara yekem a rojnameya Kurdistanê di kîjan salê de derket?', '1898', '1908', '1920', '1940', 'A', 'Hejmara yekem a rojnameya Kurdistanê di 22ê Nîsana 1898an de li Qahîreyê derket.', 'Hejmara yekem a rojnameya Kurdistanê di 22ê Nîsana 1898an de li Qahîreyê derket.', 'Kurdistan gazetesinin ilk sayısı 22 Nisan 1898''de Kahire''de çıktı; yayın 1902''ye kadar 31 sayı sürdü.', 3, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdistan_(newspaper)', NULL, 'https://en.wikipedia.org/wiki/Kurdistan_(newspaper)', 'approved', 'Kurmancî', 1, now()),
('ddfdba5b-1274-57a6-9a51-22ef967e74f9', (select id from categories where name = 'Dîrok'), 'ku-kmr', 'Kîjan bajarê Kurdistanê li ser riyên bazirganiyê yên navbera Anatolya û Mezopotamyayê navendek bû?', 'Stenbol', 'Qahîre', 'Şam', 'Amed', 'D', 'Amed li ser riyên bazirganiyê yên di navbera Anatolya û Mezopotamyayê de navendeke girîng bû.', 'Amed li ser riyên bazirganiyê yên di navbera Anatolya û Mezopotamyayê de navendeke girîng bû.', 'Amed (Diyarbakır), Anadolu ile Mezopotamya arasındaki kara ticaret yollarında önemli bir kavşak ve pazar merkeziydi.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Diyarbakır', NULL, 'https://en.wikipedia.org/wiki/Diyarbakır', 'approved', 'Kurmancî', 1, now()),
('112b4e63-95c6-5a17-90c0-d977dd9f4fa8', (select id from categories where name = 'Edebiyat'), 'ku-kmr', 'Di helbesta klasîk a Kurmancî de, kîjan têgeh ji bo rêzkirina dengan tê bikaranîn?', 'Îmge', 'Metn', 'Serhatî', 'Rîtim', 'D', 'Rîtim di helbestê de rêzkirina dengan e; ew ji bo ahengê tê bikaranîn.', 'Rîtim di helbestê de rêzkirina dengan e; ew ji bo ahengê tê bikaranîn.', 'Ritim, şiirde seslerin dizilişidir; ahenk için kullanılır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Rhythm', NULL, 'https://en.wikipedia.org/wiki/Rhythm', 'approved', 'Kurmancî', 1, now()),
('5a8b9d42-8fa9-5a3f-958b-4d267d44b17b', (select id from categories where name = 'Edebiyat'), 'ku-kmr', 'Di fabla "Gur û Rovî" de, gur gef li rovî dixwe ku eger guh nede wê çi bike?', 'Wê wî bixwe', 'Wê wî ji hêlînê derxe', 'Wê wî bide şêr', 'Wê wî bike xulamê xwe yê hertimî', 'A', 'Di fablê de gur rovî neçar dike ku jê re xwarin bibîne û gef lê dixwe ku eger guh nede wê wî bixwe. Rovî di dawiyê de bi jîrbûna xwe xilas dibe.', 'Di fablê de gur rovî neçar dike ku jê re xwarin bibîne û gef lê dixwe ku eger guh nede wê wî bixwe. Rovî di dawiyê de bi jîrbûna xwe xilas dibe.', 'Fablda kurt, tilkiyi kendisine yiyecek bulmaya zorlar ve itaat etmezse onu yemekle tehdit eder. Tilki sonunda zekâsıyla kurtulur.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/The_Wolf_and_the_Fox', NULL, 'https://en.wikipedia.org/wiki/The_Wolf_and_the_Fox', 'approved', 'Kurmancî', 1, now()),
('8ce01300-f3d6-567b-b974-d911d822b184', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Cudahiya sereke ya di navbera cureyên dengbêjiyê "Kilam" û "Lawik/Heyranok" de çi ye?', 'Kilam tenê bi tembûrê tê gotin, Lawik tenê bi def û zirneyê tê lêdan', 'Kilam tenê ji bo zarokan e, Lawik tenê di şînan de tê xwendin', 'Kilam li ser dîrok û şeran bi awayekî resîtatîf e; Lawik li ser evîn û hestan e', 'Kilam bi zimanê erebî ye, Lawik tenê bi zaravayê hewramî ye', 'C', 'Kilam bîra dîrokî û qehremaniyan bi şêwaza resîtatîf vedibêje; lawik û heyranok stranên lîrîk ên li ser evînê ne.', 'Kilam bîra dîrokî û qehremaniyan bi şêwaza resîtatîf vedibêje; lawik û heyranok stranên lîrîk ên li ser evînê ne.', 'Kilamlar tarihsel ve epik olayları serbest vezin ve anlatıyla aktarırken, lawik ve heyranoklar lirik aşk ve duygu şarkılarıdır.', 4, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Dengb%C3%AAj', NULL, 'https://en.wikipedia.org/wiki/Dengb%C3%AAj', 'approved', 'Kurmancî', 1, now()),
('f4abd4ee-9c1a-55cb-a3e7-c21418877186', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Mala Dengbêjan a ku wek navendeke girîng a kevneşopiya dengbêjiyê tê naskirin li kîjan bajarî ye?', 'Stenbol', 'Qahîre', 'Tahran', 'Amed', 'D', 'Amed (Diyarbekir) wekî navenda kevneşopiya dengbêjiyê tê hesibandin. Stenbol, Qahîre û Tahran ne navendên vê kevneşopiyê ne.', 'Amed (Diyarbekir) wekî navenda kevneşopiya dengbêjiyê tê hesibandin. Stenbol, Qahîre û Tahran ne navendên vê kevneşopiyê ne.', 'Diyarbakır, dengbêjlik geleneğinin merkezi olarak kabul edilir. İstanbul, Kahire ve Tahran bu geleneğin merkezleri değildir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Dengb%C3%AAj', NULL, 'https://en.wikipedia.org/wiki/Dengb%C3%AAj', 'approved', 'Kurmancî', 1, now()),
('d03bcb83-a75a-5562-a252-0b40ecbc27b2', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Dengbêj bi piranî kilamên xwe li ser kîjan mijaran dibêjin?', 'Evîn, dîrok û şer', 'Astronomî', 'Matematîk', 'Teknolojî', 'A', 'Dengbêj bi piranî kilamên xwe li ser evîn, dîrok û şer dibêjin. Ev mijar di nav kevneşopiya dengbêjiyê de navendî ne, ne astronomî, matematîk an jî teknolojî.', 'Dengbêj bi piranî kilamên xwe li ser evîn, dîrok û şer dibêjin. Ev mijar di nav kevneşopiya dengbêjiyê de navendî ne, ne astronomî, matematîk an jî teknolojî.', 'Dengbêjler kilamlarını çoğunlukla aşk, tarih ve savaş hakkında söylerler. Bu konular dengbêjlik geleneğinde merkezidir, astronomi, matematik veya teknoloji değil.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Dengb%C3%AAj', NULL, 'https://en.wikipedia.org/wiki/Dengb%C3%AAj', 'approved', 'Kurmancî', 1, now()),
('ac81eb47-26db-5e7c-9197-260dd1e75603', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Dengbêj bi piranî kilamên xwe li kû derê dibêjin?', 'Di şanoyan de', 'Di konseran de', 'Di civatan de', 'Di radyoyê de', 'C', 'Dengbêj bi piranî kilamên xwe di civatan de dibêjin. Şano, konser û radyo ne cihên kevneşopî yên dengbêjiyê ne.', 'Dengbêj bi piranî kilamên xwe di civatan de dibêjin. Şano, konser û radyo ne cihên kevneşopî yên dengbêjiyê ne.', 'Dengbêjler kilamlarını çoğunlukla toplantılarda söylerler. Tiyatro, konser ve radyo, dengbêjliğin geleneksel mekânları değildir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Dengb%C3%AAj', NULL, 'https://en.wikipedia.org/wiki/Dengb%C3%AAj', 'approved', 'Kurmancî', 1, now()),
('66e2900c-50f6-5fab-9751-688dfaedadc2', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Dengbêj bi piranî kilamên xwe ji bo kîjan armancê dibêjin?', 'Ji bo vegotina dîrokê', 'Ji bo dansê', 'Ji bo reklamê', 'Ji bo fêrbûna ziman', 'A', 'Dengbêj bi piranî kilamên xwe ji bo vegotina dîrokê dibêjin. Dans, reklam û fêrbûna ziman ne armancên sereke yên dengbêjiyê ne.', 'Dengbêj bi piranî kilamên xwe ji bo vegotina dîrokê dibêjin. Dans, reklam û fêrbûna ziman ne armancên sereke yên dengbêjiyê ne.', 'Dengbêjler kilamlarını çoğunlukla tarih anlatmak için söylerler. Dans, reklam ve dil öğrenmek dengbêjliğin temel amaçları değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Dengb%C3%AAj', NULL, 'https://en.wikipedia.org/wiki/Dengb%C3%AAj', 'approved', 'Kurmancî', 1, now()),
('cfc98f23-34fc-50dd-8576-63c633c86207', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Dengbêjî di nav çanda Kurdî de bi piranî ji bo kîjan nifşî tê vegotin?', 'Ji bo ciwanan', 'Ji bo hemû nifşan', 'Ji bo zarokan', 'Ji bo pîran', 'B', 'Dengbêjî di nav çanda Kurdî de ji bo hemû nifşan tê vegotin. Ew ne tenê ji bo ciwanan, zarokan an jî pîran e.', 'Dengbêjî di nav çanda Kurdî de ji bo hemû nifşan tê vegotin. Ew ne tenê ji bo ciwanan, zarokan an jî pîran e.', 'Dengbêjlik Kürt kültüründe tüm nesiller için icra edilir. Sadece gençler, çocuklar veya yaşlılar için değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Dengb%C3%AAj', NULL, 'https://en.wikipedia.org/wiki/Dengb%C3%AAj', 'approved', 'Kurmancî', 1, now()),
('f785eea6-714d-516c-9d86-e0dac9cf176b', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Cudahiya sereke ya di navbera ekola dengbêjiyê ya "Serhedê" û ya "Botanê" de di kîjan şêwazê de ye?', 'Serhed tenê bi piyanoyê tê gotin, Botan tenê bi kemançeyê tê lêdan', 'Serhed tenê ji bo mêran e, Botan tenê ji aliyê zarokan ve tê vegotin', 'Serhed bi dengê bilind û lîrîk-epîk e; Botan bêhtir rîtmîk û bi kontrola henaseyê ye', 'Serhed li ser mîtolojiya yewnanî ye, Botan tenê li ser nêçîrvaniyê ye', 'C', 'Ekola Serhedê bi qêrîn û dengê bilind ê deşt û çiyayan navdar e; ya Botanê bi melodiyên nermtir û rîtmên taybet tê naskirin.', 'Ekola Serhedê bi qêrîn û dengê bilind ê deşt û çiyayan navdar e; ya Botanê bi melodiyên nermtir û rîtmên taybet tê naskirin.', 'Serhed ekolü tiz ve gırtlaktan gelen yankılı haykırışlarla öne çıkarken; Botan ekolü daha melizmatik ve ritmik nüanslar taşır.', 4, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Temb%C3%BBr', NULL, 'https://en.wikipedia.org/wiki/Temb%C3%BBr', 'approved', 'Kurmancî', 1, now()),
('7f583586-701f-52a5-a1a6-67a3f02836b5', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Tembûr bi piranî di kîjan herêmê de tê bikaranîn?', 'Herêma Alpê', 'Herêma Amazonê', 'Herêma Kurdistanê', 'Herêma Antarktîkayê', 'C', 'Tembûr bi piranî di herêma Kurdistanê û deverên derdorê de tê bikaranîn.', 'Tembûr bi piranî di herêma Kurdistanê û deverên derdorê de tê bikaranîn.', 'Tembur çoğunlukla Kürdistan bölgesi ve çevresinde kullanılır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Temb%C3%BBr', NULL, 'https://en.wikipedia.org/wiki/Temb%C3%BBr', 'approved', 'Kurmancî', 1, now()),
('c18ce96b-81a5-523c-97a0-c99bb9ecc5de', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Zirne bi piranî li gel kîjan amûrê tê lêdan?', 'Dahol', 'Tembûr', 'Bilûr', 'Keman', 'A', 'Zirne bi piranî li gel daholê (davul) tê lêdan da ku rîtmek xurt peyda bibe.', 'Zirne bi piranî li gel daholê (davul) tê lêdan da ku rîtmek xurt peyda bibe.', 'Zirne, güçlü bir ritim elde etmek için çoğunlukla dahol (davul) ile birlikte çalınır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Zurna', NULL, 'https://en.wikipedia.org/wiki/Zurna', 'approved', 'Kurmancî', 1, now()),
('a371b0ef-3276-5c30-94e9-0cc4d4eb604c', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Zirne bi piranî di kîjan çandê de tê bikaranîn?', 'Çanda Skandînavyayê', 'Çanda Amerîkaya Başûr', 'Çanda Rojhilata Navîn', 'Çanda Awistralyayê', 'C', 'Zirne bi piranî di çanda Rojhilata Navîn û Anatoliyê de tê bikaranîn.', 'Zirne bi piranî di çanda Rojhilata Navîn û Anatoliyê de tê bikaranîn.', 'Zurna çoğunlukla Orta Doğu ve Anadolu kültüründe kullanılır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Zurna', NULL, 'https://en.wikipedia.org/wiki/Zurna', 'approved', 'Kurmancî', 1, now()),
