('48305146-5162-512d-b285-ecf8445472b6', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de dema niha ji bo lêkera "vekirin" çi ye?', 'vekir', 'vedikir', 'veke', 'vedike', 'D', 'Dema niha ya "vekirin" bi pêşgira "di-" û paşgira "-e" tê çêkirin, loma "vedike" rast e. "Vekir" dema borî ye, "vedikir" dema borî ya berdewam e û "veke" ferman e.', 'Dema niha ya "vekirin" bi pêşgira "di-" û paşgira "-e" tê çêkirin, loma "vedike" rast e. "Vekir" dema borî ye, "vedikir" dema borî ya berdewam e û "veke" ferman e.', '"Vekirin" fiilinin şimdiki zamanı "di-" öneki ve "-e" son ekiyle oluşturulur, bu yüzden "vedike" doğrudur. "Vekir" geçmiş zaman, "vedikir" sürekli geçmiş zaman ve "veke" emir kipidir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurmanji', NULL, 'https://en.wikipedia.org/wiki/Kurmanji', 'approved', 'Kurmancî', 1, now()),
('6ba97e2a-49de-5e4d-a8a6-ad495fa6e7db', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de dema niha ji bo lêkera "şandin" çawa tê nivîsîn?', 'şand', 'dişand', 'bişîne', 'dişîne', 'D', 'Dema niha ya "şandin" bi pêşgira "di-" û paşgira "-e" tê çêkirin, loma "dişîne" rast e. "Şand" dema borî ye, "dişand" dema borî ya berdewam e û "bişîne" ferman e.', 'Dema niha ya "şandin" bi pêşgira "di-" û paşgira "-e" tê çêkirin, loma "dişîne" rast e. "Şand" dema borî ye, "dişand" dema borî ya berdewam e û "bişîne" ferman e.', '"Şandin" fiilinin şimdiki zamanı "di-" öneki ve "-e" son ekiyle oluşturulur, bu yüzden "dişîne" doğrudur. "Şand" geçmiş zaman, "dişand" sürekli geçmiş zaman ve "bişîne" emir kipidir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurmanji', NULL, 'https://en.wikipedia.org/wiki/Kurmanji', 'approved', 'Kurmancî', 1, now()),
('2613aad1-d1c6-5551-b3ae-495631ac006a', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kîjan form ji bo dema niha ya kurmancî rast e?', 'ez diçim', 'ez çûm', 'ez diçûm', 'ez herim', 'A', 'Dema niha ya "çûn" bi "ez diçim" tê gotin. "Ez çûm" dema borî ye, "ez diçûm" dema borî ya berdewam e û "ez herim" dema bê ya xwestekî ye.', 'Dema niha ya "çûn" bi "ez diçim" tê gotin. "Ez çûm" dema borî ye, "ez diçûm" dema borî ya berdewam e û "ez herim" dema bê ya xwestekî ye.', '"Çûn" fiilinin şimdiki zamanı "ez diçim" ile söylenir. "Ez çûm" geçmiş zaman, "ez diçûm" sürekli geçmiş zaman ve "ez herim" istek kipi gelecek zamandır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurmanji', NULL, 'https://en.wikipedia.org/wiki/Kurmanji', 'approved', 'Kurmancî', 1, now()),
('e21000dc-2ecf-5ad6-8229-62032e1dc228', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kîjan form ji bo dema niha ya kurmancî ya "hatin" rast e?', 'hat', 'tê', 'dihat', 'bê', 'B', 'Dema niha ya "hatin" bi "tê" tê gotin. "Hat" dema borî ye, "dihat" dema borî ya berdewam e û "bê" ferman e.', 'Dema niha ya "hatin" bi "tê" tê gotin. "Hat" dema borî ye, "dihat" dema borî ya berdewam e û "bê" ferman e.', '"Hatin" fiilinin şimdiki zamanı "tê" ile söylenir. "Hat" geçmiş zaman, "dihat" sürekli geçmiş zaman ve "bê" emir kipidir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurmanji', NULL, 'https://en.wikipedia.org/wiki/Kurmanji', 'approved', 'Kurmancî', 1, now()),
('3fcff0ec-f16f-55b6-b7dc-0bcb01c5a0fb', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kîjan form ji bo dema niha ya kurmancî ya "girtin" rast e?', 'girt', 'digirt', 'digire', 'bigire', 'C', 'Dema niha ya "girtin" bi pêşgira "di-" û paşgira "-e" tê çêkirin, loma "digire" rast e. "Girt" dema borî ye, "digirt" dema borî ya berdewam e û "bigire" ferman e.', 'Dema niha ya "girtin" bi pêşgira "di-" û paşgira "-e" tê çêkirin, loma "digire" rast e. "Girt" dema borî ye, "digirt" dema borî ya berdewam e û "bigire" ferman e.', '"Girtin" fiilinin şimdiki zamanı "di-" öneki ve "-e" son ekiyle oluşturulur, bu yüzden "digire" doğrudur. "Girt" geçmiş zaman, "digirt" sürekli geçmiş zaman ve "bigire" emir kipidir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurmanji', NULL, 'https://en.wikipedia.org/wiki/Kurmanji', 'approved', 'Kurmancî', 1, now()),
('ae10350c-3952-56c2-a91a-ed0bcf1dcb25', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kîjan form ji bo dema niha ya kurmancî ya "anîn" rast e?', 'anî', 'dianî', 'bîne', 'tîne', 'D', 'Dema niha ya "anîn" bi "tîne" tê gotin. "Anî" dema borî ye, "dianî" dema borî ya berdewam e û "bîne" ferman e.', 'Dema niha ya "anîn" bi "tîne" tê gotin. "Anî" dema borî ye, "dianî" dema borî ya berdewam e û "bîne" ferman e.', '"Anîn" fiilinin şimdiki zamanı "tîne" ile söylenir. "Anî" geçmiş zaman, "dianî" sürekli geçmiş zaman ve "bîne" emir kipidir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurmanji', NULL, 'https://en.wikipedia.org/wiki/Kurmanji', 'approved', 'Kurmancî', 1, now()),
('9e9c4c53-3b39-584c-a7e3-b6cd55063345', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kîjan hevok di kurmancî de bi awayê erênî hatiye nivîsîn?', 'Ew naçe bajêr', 'Ew naçe malê', 'Ew naçe dibistanê', 'Ew diçe bajêr', 'D', 'Hevoka "ew diçe bajêr" bi awayê erênî ye ji ber ku lêkera "diçe" bi awayê erênî hatiye bikaranîn. Yên din bi pêşgira "na-" neyînî ne.', 'Hevoka "ew diçe bajêr" bi awayê erênî ye ji ber ku lêkera "diçe" bi awayê erênî hatiye bikaranîn. Yên din bi pêşgira "na-" neyînî ne.', '"Ew diçe bajêr" cümlesi olumludur çünkü "diçe" fiili olumlu biçimde kullanılmıştır. Diğerleri "na-" öneki ile olumsuzdur.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', 'approved', 'Kurmancî', 1, now()),
('cee24b7e-89c9-538f-9684-b6bee0e85a82', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de "li ser" çi nîşan dide?', 'Cihê jêrîn', 'Cihê hundir', 'Cihê jorîn', 'Cihê derve', 'C', '"Li ser" tê wateya "li ser" an "li jor" û cihê jorîn nîşan dide.', '"Li ser" tê wateya "li ser" an "li jor" û cihê jorîn nîşan dide.', '"Li ser", "üzerinde" veya "üstünde" anlamına gelir ve üst konumu belirtir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_grammar', NULL, 'https://en.wikipedia.org/wiki/Kurdish_grammar', 'approved', 'Kurmancî', 1, now()),
('131038db-c4b7-5ded-9024-8cf7df14d4e0', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de "li gel" çi nîşan dide?', 'Cihê jorîn', 'Cihê jêrîn', 'Sedem', 'Hevaltî an pê re bûn', 'D', '"Li gel" tê wateya "bi ... re" an "li gel" û hevaltiyê nîşan dide.', '"Li gel" tê wateya "bi ... re" an "li gel" û hevaltiyê nîşan dide.', '"Li gel", "... ile birlikte" veya "... ile" anlamına gelir ve arkadaşlığı/birlikteliği belirtir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_grammar', NULL, 'https://en.wikipedia.org/wiki/Kurdish_grammar', 'approved', 'Kurmancî', 1, now()),
('a4b7f40f-be04-5029-a3eb-770684423a11', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di metbexê de, kîjan amûr ji bo birîna tiştan tê bikaranîn?', 'Kefçî', 'Kêr', 'Çetel', 'Sênî', 'B', 'Kêr ji bo birînê ye; kefçî, çetel û sênî ji bo xwarin û servîsê ne.', 'Kêr ji bo birînê ye; kefçî, çetel û sênî ji bo xwarin û servîsê ne.', 'Bıçak kesmek içindir; kaşık, çatal ve tabak yemek ve servis içindir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Knife', NULL, 'https://en.wikipedia.org/wiki/Knife', 'approved', 'Kurmancî', 1, now()),
('5bdba7f8-3cc3-531b-b7b9-68b76fc71985', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di hundirê malê de, kîjan cih ji bo xwarinê tê bikaranîn?', 'Serşok', 'Odeya razanê', 'Bexçe', 'Metbex', 'D', 'Metbex cihê çêkirin û xwarina xwarinê ye; serşok, odeya razanê û bexçe ne ji bo xwarinê ne.', 'Metbex cihê çêkirin û xwarina xwarinê ye; serşok, odeya razanê û bexçe ne ji bo xwarinê ne.', 'Mutfak yemek yapma ve yeme yeridir; banyo, yatak odası ve bahçe yemek için değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kitchen', NULL, 'https://en.wikipedia.org/wiki/Kitchen', 'approved', 'Kurmancî', 1, now()),
('6b79f751-3643-52e4-8a0b-6514809e6074', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di malê de, kîjan cih ji bo rûniştina mêvanan tê bikaranîn?', 'Serşok', 'Dolab', 'Metbex', 'Odeya rûniştinê', 'D', 'Odeya rûniştinê ji bo mêvanan e; serşok, dolab û metbex ne ji bo mêvanan in.', 'Odeya rûniştinê ji bo mêvanan e; serşok, dolab û metbex ne ji bo mêvanan in.', 'Oturma odası misafirler içindir; banyo, dolap ve mutfak misafirler için değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Living_room', NULL, 'https://en.wikipedia.org/wiki/Living_room', 'approved', 'Kurmancî', 1, now()),
('986d3d29-c69b-5d1c-9956-ee98728c0d24', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di malê de, kîjan cih ji bo hilanîna xwarinan tê bikaranîn?', 'Dolaba xwarinê', 'Serşok', 'Odeya razanê', 'Bexçe', 'A', 'Dolaba xwarinê ji bo hilanîna xwarinan e; serşok, odeya razanê û bexçe ne ji bo hilanînê ne.', 'Dolaba xwarinê ji bo hilanîna xwarinan e; serşok, odeya razanê û bexçe ne ji bo hilanînê ne.', 'Yiyecek dolabı yiyecek saklamak içindir; banyo, yatak odası ve bahçe saklamak için değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Pantry', NULL, 'https://en.wikipedia.org/wiki/Pantry', 'approved', 'Kurmancî', 1, now()),
('9809962a-b3a5-551f-a235-3a241d253c38', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di malê de, kîjan cih ji bo hilanîna kincan tê bikaranîn?', 'Dolaba kincan', 'Metbex', 'Serşok', 'Bexçe', 'A', 'Dolaba kincan ji bo kincan e; metbex, serşok û bexçe ne ji bo kincan in.', 'Dolaba kincan ji bo kincan e; metbex, serşok û bexçe ne ji bo kincan in.', 'Elbise dolabı kıyafetler içindir; mutfak, banyo ve bahçe kıyafetler için değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Wardrobe', NULL, 'https://en.wikipedia.org/wiki/Wardrobe', 'approved', 'Kurmancî', 1, now()),
('e1468b1e-2452-55c6-8003-2e0d33febda0', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kîjan tişt ji bo vekirina deriyê malê tê bikaranîn?', 'Mifte', 'Kûp', 'Sênî', 'Kursî', 'A', 'Mifte ji bo vekirina derî ye; kûp, sênî û kursî ne ji bo vekirinê ne.', 'Mifte ji bo vekirina derî ye; kûp, sênî û kursî ne ji bo vekirinê ne.', 'Anahtar kapı açmak içindir; bardak, tabak ve sandalye açmak için değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Key_(lock)', NULL, 'https://en.wikipedia.org/wiki/Key_(lock)', 'approved', 'Kurmancî', 1, now()),
('38d1f4f1-1fb7-552f-a413-feb028c0fa66', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Ji bo danîna pirtûkan, kîjan mobîlya tê bikaranîn?', 'Kursî', 'Dolaba pirtûkan', 'Mase', 'Nivîn', 'B', 'Dolaba pirtûkan ji bo pirtûkan e; kursî, mase û nivîn ne ji bo pirtûkan in.', 'Dolaba pirtûkan ji bo pirtûkan e; kursî, mase û nivîn ne ji bo pirtûkan in.', 'Kitap dolabı kitaplar içindir; sandalye, masa ve yatak kitaplar için değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Bookshelf', NULL, 'https://en.wikipedia.org/wiki/Bookshelf', 'approved', 'Kurmancî', 1, now()),
('e952ce1f-8aec-5682-b9dd-ce4a5639eecd', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di serşokê de, kîjan tişt ji bo şuştina destan tê bikaranîn?', 'Sabûn', 'Kûp', 'Sênî', 'Kêr', 'A', 'Sabûn ji bo şuştinê ye; kûp, sênî û kêr ne ji bo şuştinê ne.', 'Sabûn ji bo şuştinê ye; kûp, sênî û kêr ne ji bo şuştinê ne.', 'Sabun yıkamak içindir; testi, sini ve bıçak yıkamak için değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Soap', NULL, 'https://en.wikipedia.org/wiki/Soap', 'approved', 'Kurmancî', 1, now()),
('1dc766f2-5798-5815-96a0-4860763e3501', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Ji bo ronahiya derve, kîjan tişt tê bikaranîn?', 'Mase', 'Dolab', 'Çira', 'Ref', 'C', 'Çira ji bo ronahiya derve ye; mase, dolab û ref ne ji bo ronahiyê ne.', 'Çira ji bo ronahiya derve ye; mase, dolab û ref ne ji bo ronahiyê ne.', 'Lamba dışarıyı aydınlatmak içindir; masa, dolap ve raf aydınlatma için değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Lantern', NULL, 'https://en.wikipedia.org/wiki/Lantern', 'approved', 'Kurmancî', 1, now()),
('cab1acb7-55c4-58a7-b0e5-deba45009426', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kîjan tişt ji bo çêkirina çayê tê bikaranîn?', 'Kûp', 'Çaydan', 'Sênî', 'Kêr', 'B', 'Çaydan ji bo çêkirina çayê ye; kûp, sênî û kêr ne ji bo çêkirina çayê ne.', 'Çaydan ji bo çêkirina çayê ye; kûp, sênî û kêr ne ji bo çêkirina çayê ne.', 'Çaydanlık çay yapmak içindir; testi, sini ve bıçak çay yapmak için değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Teapot', NULL, 'https://en.wikipedia.org/wiki/Teapot', 'approved', 'Kurmancî', 1, now()),
('8c67cc03-b3fc-59ec-8a9f-de39efb4e3eb', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de peyva "dar" ji bo çi tê bikaranîn?', 'riwekek e ku fêkî dide', 'ajalek e ku difire', 'çiyayekî bilind', 'cureyekî avê', 'A', 'Peyva "dar" di kurmancî de ji bo riwekên mezin û bi qurm tê bikaranîn, wek dara sêvê. Ew ne ajal, ne çiya û ne jî av e.', 'Peyva "dar" di kurmancî de ji bo riwekên mezin û bi qurm tê bikaranîn, wek dara sêvê. Ew ne ajal, ne çiya û ne jî av e.', '"Dar" kelimesi Kürtçede, elma ağacı gibi gövdeli büyük bitkiler için kullanılır. O bir hayvan, dağ veya su değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Tree', NULL, 'https://en.wikipedia.org/wiki/Tree', 'approved', 'Kurmancî', 1, now()),
('77744a3f-08cd-5a19-8545-fba4968ad2a5', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de "av" çi ye?', 'tiştekî hişk e ku di erdê de ye', 'ajalek e ku di avê de dijî', 'şilek e ku ji bo jiyanê pêwîst e', 'riwekek e ku li ber avê şîn dibe', 'C', 'Av şilek e ku ji bo jiyana mirovan, ajal û riwekan pêwîst e. Ew ne hişk e, ne ajal e û ne jî riwek e.', 'Av şilek e ku ji bo jiyana mirovan, ajal û riwekan pêwîst e. Ew ne hişk e, ne ajal e û ne jî riwek e.', 'Su, insanların, hayvanların ve bitkilerin yaşamı için gerekli olan bir sıvıdır. Katı değildir, bir hayvan veya bitki değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Water', NULL, 'https://en.wikipedia.org/wiki/Water', 'approved', 'Kurmancî', 1, now()),
('7a232a95-76b0-58cb-b56e-9a9c47ff5446', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kîjan ajal bi piranî di çol û beyaran de dijî?', 'hêştir', 'ker', 'mih', 'ga', 'A', 'Hêştir ajalek e ku bi piranî li çol û beyaran dijî û li wir tê bikaranîn. Ker, mih û ga jî li gundan tên xwedîkirin lê hêştir ji wan bêtir bi çolê ve girêdayî ye.', 'Hêştir ajalek e ku bi piranî li çol û beyaran dijî û li wir tê bikaranîn. Ker, mih û ga jî li gundan tên xwedîkirin lê hêştir ji wan bêtir bi çolê ve girêdayî ye.', 'Deve, çoğunlukla çöl ve kırsal alanlarda yaşayan ve orada kullanılan bir hayvandır. Eşek, koyun ve sığır da köylerde beslenir ancak deve onlardan daha çok çölle ilişkilidir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Camel', NULL, 'https://en.wikipedia.org/wiki/Camel', 'approved', 'Kurmancî', 1, now()),
('75c2140f-7d76-5625-9dc6-d256096a5783', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de peyva "xew" çi wateyê dide?', 'revîna ajalan', 'xwarina riwekan', 'nivistina mirovan', 'vexwarina avê', 'C', 'Xew di kurmancî de rewşa nivistinê ye. Ew ne revîn, ne xwarin û ne jî vexwarin e.', 'Xew di kurmancî de rewşa nivistinê ye. Ew ne revîn, ne xwarin û ne jî vexwarin e.', 'Xew, Kürtçede uyuma durumudur. Kaçmak, yemek veya içmek değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Sleep', NULL, 'https://en.wikipedia.org/wiki/Sleep', 'approved', 'Kurmancî', 1, now()),
('4615ffad-d65b-536e-a026-89f8de85c993', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de hejmara 7 çawa tê nivîsîn?', 'heşt', 'neh', 'şeş', 'heft', 'D', 'Di kurmancî de hejmara 7 "heft" e. "Heşt" 8, "neh" 9 û "şeş" 6 e.', 'Di kurmancî de hejmara 7 "heft" e. "Heşt" 8, "neh" 9 û "şeş" 6 e.', 'Kürtçede 7 sayısı "heft"tir. "Heşt" 8, "neh" 9 ve "şeş" 6''dır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', 'approved', 'Kurmancî', 1, now()),
('9627a8c9-b3ad-5ab5-80e1-d596fb5984d6', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Kîjan hejmar di kurmancî de wek "bîst" tê nivîsîn?', '20', '30', '40', '50', 'A', '"Bîst" di kurmancî de hejmara 20 ye. 30 "sî", 40 "çil" û 50 "pêncî" ye.', '"Bîst" di kurmancî de hejmara 20 ye. 30 "sî", 40 "çil" û 50 "pêncî" ye.', '"Bîst" Kürtçede 20 sayısıdır. 30 "sî", 40 "çil" ve 50 "pêncî"dir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', 'approved', 'Kurmancî', 1, now()),
('d8579cf2-1ea4-5ec5-909c-e5dfe9899e93', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de "nehem" li kîjan rêza hejmarî tê?', 'Nehemîn (9.)', '10', '11', '12', 'A', '"Nehem" hejmara rêzê ye: neh + em. Hejmara sade "neh" e.', '"Nehem" hejmara rêzê ye: neh + em. Hejmara sade "neh" e.', '"Nehem" sıra sayısıdır: neh + em. Sayı olarak dokuz "neh"tir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', 'approved', 'Kurmancî', 1, now()),
('70caabef-95d2-5b4f-9326-89961c644ec5', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de "pêncem" li kîjan rêza hejmarî tê?', 'Pêncemîn (5.)', '6', '7', '8', 'A', '"Pêncem" hejmara rêzê ye: pênc + em. Hejmara sade "pênc" e.', '"Pêncem" hejmara rêzê ye: pênc + em. Hejmara sade "pênc" e.', '"Pêncem" sıra sayısıdır: pênc + em. Sayı olarak beş "pênc"tir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', 'approved', 'Kurmancî', 1, now()),
('78139f27-5d51-5e9d-ad88-481d0e339a7b', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de hejmara 4 çawa tê nivîsîn?', 'pênc', 'sê', 'çar', 'du', 'C', 'Hejmara 4 di kurmancî de "çar" e. "Pênc" 5, "sê" 3 û "du" 2 ye.', 'Hejmara 4 di kurmancî de "çar" e. "Pênc" 5, "sê" 3 û "du" 2 ye.', 'Kürtçede 4 sayısı "çar"dır. "Pênc" 5, "sê" 3 ve "du" 2''dir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', 'approved', 'Kurmancî', 1, now()),
('8d31b1e7-941f-5dce-8ef3-3dc9ef4462e2', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de ji bo pirsîna dema borî kîjan peyva pirsyariyê tê bikaranîn?', 'Kengî', 'Çi', 'Kî', 'Çima', 'A', 'Peyva "kengî" di kurmancî de ji bo pirsîna demê tê bikaranîn, û dema borî jî di nav de ye. "Çi" ji bo tiştan, "kî" ji bo kesan û "çima" ji bo sedemê tê bikaranîn.', 'Peyva "kengî" di kurmancî de ji bo pirsîna demê tê bikaranîn, û dema borî jî di nav de ye. "Çi" ji bo tiştan, "kî" ji bo kesan û "çima" ji bo sedemê tê bikaranîn.', 'Kurmanccada "kengî" kelimesi zamanı sormak için kullanılır ve geçmiş zaman da buna dahildir. "Çi" nesneler için, "kî" kişiler için ve "çima" sebep için kullanılır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', 'approved', 'Kurmancî', 1, now()),
('41c15c98-367b-5f0f-a620-1a57d0490b95', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de ji bo kesekî ku bi zanebûn û hişmendî tevdigere kîjan rengdêr tê bikaranîn?', 'zîrek', 'xwerû', 'tembel', 'hêdî', 'A', 'Rengdêra "zîrek" di kurmancî de ji bo kesên hişmend û çalak tê bikaranîn. "Tembel" û "hêdî" dijberên wê ne, "xwerû" jî wateyeke din e.', 'Rengdêra "zîrek" di kurmancî de ji bo kesên hişmend û çalak tê bikaranîn. "Tembel" û "hêdî" dijberên wê ne, "xwerû" jî wateyeke din e.', '"Zîrek" (zeki) sıfatı Kürtçede anlayışlı ve aktif kişiler için kullanılır. "Tembel" (tembel) ve "hêdî" (yavaş) bunun zıttıdır, "xwerû" (saf) ise farklı bir anlama sahiptir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', 'approved', 'Kurmancî', 1, now()),
('30e9cef1-de6d-5c47-9197-268d3ea36a2c', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de ji bo jina birayê mirov çi tê gotin?', 'Jinbira', 'Bûk', 'Dê', 'Xwişk', 'A', '"Jinbira" ji bo jina birayê mirov tê bikaranîn. "Bûk" ji bo jina kurê mirov e, "dê" ji bo dayikê ye, "xwişk" jî ji bo xwişka mirov e.', '"Jinbira" ji bo jina birayê mirov tê bikaranîn. "Bûk" ji bo jina kurê mirov e, "dê" ji bo dayikê ye, "xwişk" jî ji bo xwişka mirov e.', '"Jinbira" kişinin erkek kardeşinin karısı için kullanılır. "Bûk" kişinin oğlunun karısı içindir, "dê" anne içindir, "xwişk" ise kişinin kız kardeşi içindir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Sister-in-law', NULL, 'https://en.wikipedia.org/wiki/Sister-in-law', 'approved', 'Kurmancî', 1, now()),
('ee933f3c-9662-5997-9c3f-f05be676ffef', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de ji bo kesekî ku bi lez tevdigere kîjan rengdêr tê bikaranîn?', 'hêdî', 'lezgîn', 'tembel', 'xwerû', 'B', 'Rengdêra "lezgîn" di kurmancî de ji bo kesên bi lez û bez tê bikaranîn. "Hêdî" û "tembel" dijberên wê ne, "xwerû" jî wateyeke din e.', 'Rengdêra "lezgîn" di kurmancî de ji bo kesên bi lez û bez tê bikaranîn. "Hêdî" û "tembel" dijberên wê ne, "xwerû" jî wateyeke din e.', '"Lezgîn" sıfatı Kürtçede (Kurmanci) hızlı ve çevik kişiler için kullanılır. "Hêdî" ve "tembel" zıttıdır, "xwerû" ise farklı bir anlama gelir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', 'approved', 'Kurmancî', 1, now()),
('1b8e0a84-0705-543f-bec6-db95ab55f81f', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de "çavên xwe vekirin" bi wateya xwe ya mecazî çi ye?', 'xewê ji xwe re anîn', 'hişyar bûn', 'tiştekî nû dîtin', 'girîn', 'B', '"Çavên xwe vekirin" di kurmancî de bi wateya mecazî tê wateya hişyar bûn an jî baldar bûn. Ev gotin bi wateya rastîn a vekirina çavan re têkildar nîne.', '"Çavên xwe vekirin" di kurmancî de bi wateya mecazî tê wateya hişyar bûn an jî baldar bûn. Ev gotin bi wateya rastîn a vekirina çavan re têkildar nîne.', '"Çavên xwe vekirin" Kurmanci''de mecazi anlamda uyanık olmak veya dikkatli olmak demektir. Bu deyim, gözleri açmanın gerçek anlamıyla ilgili değildir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', 'approved', 'Kurmancî', 1, now()),
('6de8d265-d6fb-533e-b6cd-ad4d3ceafa37', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Gotina "xwe avêtin ber bayî" di kurmancî de ji bo kîjan rewşê tê bikaranîn?', 'ji bo bazdanê', 'ji bo revê', 'ji bo xwe veşartinê', 'ji bo xwe spartina qederê', 'D', '"Xwe avêtin ber bayî" di kurmancî de tê wateya xwe spartina qederê an jî xwe berdan ser çarenivîsê. Ev gotin bi wateya rastîn a avêtina xwe re têkildar nîne.', '"Xwe avêtin ber bayî" di kurmancî de tê wateya xwe spartina qederê an jî xwe berdan ser çarenivîsê. Ev gotin bi wateya rastîn a avêtina xwe re têkildar nîne.', '"Xwe avêtin ber bayî" Kurmanci''de kaderine razı olmak veya kendini kaderine bırakmak anlamına gelir. Bu deyim, kendini atmanın gerçek anlamıyla ilgili değildir.', 3, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', 'approved', 'Kurmancî', 1, now()),
('6f8d52ec-5dcc-58a2-b5f5-0876acd5e481', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de "devê xwe vekirin" bi wateya xwe ya mecazî çi ye?', 'axaftin', 'xwarin xwarin', 'kenîn', 'girîn', 'A', '"Devê xwe vekirin" di kurmancî de bi wateya mecazî tê wateya axaftin an jî dest bi axaftinê kirin. Ev gotin bi wateya rastîn a vekirina devê xwe re têkildar nîne.', '"Devê xwe vekirin" di kurmancî de bi wateya mecazî tê wateya axaftin an jî dest bi axaftinê kirin. Ev gotin bi wateya rastîn a vekirina devê xwe re têkildar nîne.', '"Devê xwe vekirin" Kurmanci''de mecazi anlamda konuşmak veya konuşmaya başlamak demektir. Bu deyim, ağzını açmanın gerçek anlamıyla ilgili değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', 'approved', 'Kurmancî', 1, now()),
('1b1b7fb6-ef29-564d-b64b-cf3cc7f771e4', (select id from categories where name = 'Ziman'), 'ku-kmr', 'Di kurmancî de "devê xwe girtin" bi wateya xwe ya mecazî çi ye?', 'axaftin', 'kenîn', 'bêdeng bûn', 'girîn', 'C', '"Devê xwe girtin" di kurmancî de bi wateya mecazî tê wateya bêdeng bûn an jî neaxaftin. Ev gotin bi wateya rastîn a girtina devê xwe re têkildar nîne.', '"Devê xwe girtin" di kurmancî de bi wateya mecazî tê wateya bêdeng bûn an jî neaxaftin. Ev gotin bi wateya rastîn a girtina devê xwe re têkildar nîne.', '"Devê xwe girtin" Kurmanci''de mecazi anlamda sessiz olmak veya konuşmamak demektir. Bu deyim, ağzını kapatmanın gerçek anlamıyla ilgili değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', NULL, 'https://en.wikipedia.org/wiki/Kurdish_language', 'approved', 'Kurmancî', 1, now()),
('ece83ee3-f32e-579b-ad20-e2b19fdde422', (select id from categories where name = 'Çand'), 'ku-kmr', 'Newroz çima di 21''ê adarê de tê pîrozkirin?', 'Ji ber ku havîn dest pê dike', 'Ji ber ku roj û şev wekhev in', 'Ji ber ku zivistan dirêj dibe', 'Ji ber ku baran zêde dibare', 'B', 'Newroz bi ekinoksê ve girêdayî ye; di 21''ê adarê de roj û şev wekhev dibin û ev destpêka biharê ye.', 'Newroz bi ekinoksê ve girêdayî ye; di 21''ê adarê de roj û şev wekhev dibin û ev destpêka biharê ye.', 'Newroz ekinoks ile bağlantılıdır; 21 Mart''ta gece ve gündüz eşitlenir ve bu baharın başlangıcıdır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Nowruz', NULL, 'https://en.wikipedia.org/wiki/Nowruz', 'approved', 'Kurmancî', 1, now()),
('05192fea-4ad9-5bcc-bb29-486c8aaec213', (select id from categories where name = 'Çand'), 'ku-kmr', 'Newroz bi kîjan zimanî tê wateya "roja nû"?', 'Erebî', 'Farisî', 'Tirkî', 'Îngilîzî', 'B', 'Newroz ji du peyvan pêk tê: "new" (nû) û "roz" (roj), ku ji zimanê farisî tê.', 'Newroz ji du peyvan pêk tê: "new" (nû) û "roz" (roj), ku ji zimanê farisî tê.', 'Newroz iki kelimeden oluşur: "new" (yeni) ve "roz" (gün), Farsça''dan gelir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Nowruz', NULL, 'https://en.wikipedia.org/wiki/Nowruz', 'approved', 'Kurmancî', 1, now()),
('9dd2f74d-5177-5cdb-ab75-8f1e37917186', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di Newrozê de çi tê amadekirin?', 'Xwarinên taybet', 'Cilên reş', 'Mala vala', 'Derya', 'A', 'Di Newrozê de xwarinên taybet tên amadekirin û mirov bi hev re dixwin; ev beşek ji pîrozbahiyê ye.', 'Di Newrozê de xwarinên taybet tên amadekirin û mirov bi hev re dixwin; ev beşek ji pîrozbahiyê ye.', 'Newroz''da özel yemekler hazırlanır ve insanlar birlikte yer; bu kutlamanın bir parçasıdır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Nowruz', NULL, 'https://en.wikipedia.org/wiki/Nowruz', 'approved', 'Kurmancî', 1, now()),
('a3d71403-1758-5a77-b484-96ae8f48e88b', (select id from categories where name = 'Çand'), 'ku-kmr', 'Kîjan welat Newrozê wekî betlaneya fermî pîroz dike?', 'Fransa', 'Almanya', 'Spanya', 'Îran', 'D', 'Îran Newrozê wekî betlaneya fermî pîroz dike; ev roj li wir gelek giring e.', 'Îran Newrozê wekî betlaneya fermî pîroz dike; ev roj li wir gelek giring e.', 'İran Newroz''u resmi tatil olarak kutlar; bu gün orada çok önemlidir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Nowruz', NULL, 'https://en.wikipedia.org/wiki/Nowruz', 'approved', 'Kurmancî', 1, now()),
('d56b9eda-f43c-572b-825b-3dc115e32f6c', (select id from categories where name = 'Çand'), 'ku-kmr', 'Newroz di kîjan mehê de tê pîrozkirin?', 'Nîsan', 'Adar', 'Gulan', 'Hezîran', 'B', 'Newroz di meha adarê de tê pîrozkirin; ev meha ekinoksê ye.', 'Newroz di meha adarê de tê pîrozkirin; ev meha ekinoksê ye.', 'Newroz, Mart ayında kutlanır; bu ekinoks ayıdır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Nowruz', NULL, 'https://en.wikipedia.org/wiki/Nowruz', 'approved', 'Kurmancî', 1, now()),
('1b284bfa-ceb1-51ba-89a7-9fec89362664', (select id from categories where name = 'Çand'), 'ku-kmr', 'Newroz bi kîjan dînî ve tê girêdan?', 'Îslam', 'Xiristiyanî', 'Zerdeştî', 'Cihûtî', 'C', 'Newroz bi zerdeştiyê ve tê girêdan; ew ji dînê kevnar ê farisî ye.', 'Newroz bi zerdeştiyê ve tê girêdan; ew ji dînê kevnar ê farisî ye.', 'Newroz, Zerdüştlükle ilişkilendirilir; bu, eski İran dinidir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Nowruz', NULL, 'https://en.wikipedia.org/wiki/Nowruz', 'approved', 'Kurmancî', 1, now()),
('a3e51954-a80c-555d-abd4-68a5b6b94d80', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di Newrozê de mirov çi li xwe dikin?', 'Cilên nû', 'Cilên kevn', 'Cilên reş', 'Cilên spî', 'A', 'Di Newrozê de mirov cilên nû li xwe dikin; ev ji bo nûbûnê ye.', 'Di Newrozê de mirov cilên nû li xwe dikin; ev ji bo nûbûnê ye.', 'Newroz''da insanlar yeni kıyafetler giyer; bu yenilenme içindir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Nowruz', NULL, 'https://en.wikipedia.org/wiki/Nowruz', 'approved', 'Kurmancî', 1, now()),
('e277a51a-a22c-5c64-9483-50919628c834', (select id from categories where name = 'Çand'), 'ku-kmr', 'Newroz bi kîjan demsalê ve tê girêdan?', 'Zivistanê', 'Biharê', 'Havînê', 'Payîzê', 'B', 'Newroz bi biharê ve tê girêdan; ew destpêka biharê ye.', 'Newroz bi biharê ve tê girêdan; ew destpêka biharê ye.', 'Newroz ilkbaharla ilişkilendirilir; ilkbaharın başlangıcıdır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Nowruz', NULL, 'https://en.wikipedia.org/wiki/Nowruz', 'approved', 'Kurmancî', 1, now()),
('b0e20d72-1682-562d-b006-d2077772cd00', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di daweta kurdî de, kîjan çalakî bi gelemperî piştî xwarinê tê kirin?', 'Xew', 'Stran', 'Govend', 'Axaftin', 'C', 'Piştî xwarinê, govend bi gelemperî tê gerandin. Govend dansa kolektîf a kurdî ye ku mirov bi destên hev ve girêdidin û bi rîtma muzîkê digerin.', 'Piştî xwarinê, govend bi gelemperî tê gerandin. Govend dansa kolektîf a kurdî ye ku mirov bi destên hev ve girêdidin û bi rîtma muzîkê digerin.', 'Yemekten sonra genellikle govend oynanır. Govend, insanların el ele tutuşup müziğin ritmine göre döndüğü kolektif bir Kürt dansıdır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_dance', NULL, 'https://en.wikipedia.org/wiki/Kurdish_dance', 'approved', 'Kurmancî', 1, now()),
('b96c9067-218a-5430-8ce5-a4f690a8fffe', (select id from categories where name = 'Çand'), 'ku-kmr', 'Kîjan reng di xalîçeyên kurdî de bi gelemperî tê bikaranîn?', 'Şîn', 'Sor', 'Zer', 'Kesk', 'B', 'Rengê sor di xalîçeyên kurdî de pir caran tê bikaranîn ji ber ku ji kokên riwekan tê wergirtin û sembola jiyanê ye. Rengên din jî tên bikaranîn lê sor bi taybetî di nav kurdan de navdar e.', 'Rengê sor di xalîçeyên kurdî de pir caran tê bikaranîn ji ber ku ji kokên riwekan tê wergirtin û sembola jiyanê ye. Rengên din jî tên bikaranîn lê sor bi taybetî di nav kurdan de navdar e.', 'Kırmızı renk, bitki köklerinden elde edildiği ve yaşamın sembolü olduğu için Kürt halılarında sıklıkla kullanılır. Diğer renkler de kullanılır ancak kırmızı özellikle Kürtler arasında ünlüdür.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_carpet', NULL, 'https://en.wikipedia.org/wiki/Kurdish_carpet', 'approved', 'Kurmancî', 1, now()),
('c2bb2a42-de45-5994-9754-68cd18d201c3', (select id from categories where name = 'Çand'), 'ku-kmr', 'Kîjan amûra muzîkê ya kurdî bi gelemperî ji bo govendê tê bikaranîn û dişibe kemanê?', 'Kemançe', 'Tembûr', 'Zirna', 'Def', 'A', 'Kemançe amûreke muzîkê ya kurdî ye ku bi kevanê tê lêxistin û dişibe kemanê, lê dengê wê cuda ye.', 'Kemançe amûreke muzîkê ya kurdî ye ku bi kevanê tê lêxistin û dişibe kemanê, lê dengê wê cuda ye.', 'Kemançe, yayla çalınan ve kemana benzeyen, ancak sesi farklı olan bir Kürt müzik aletidir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kamancheh', NULL, 'https://en.wikipedia.org/wiki/Kamancheh', 'approved', 'Kurmancî', 1, now()),
('0f6fb493-7e0f-5167-a31b-acf14d1a0f03', (select id from categories where name = 'Çand'), 'ku-kmr', 'Kîjan amûra muzîkê ya kurdî bi gelemperî ji bo govendê tê bikaranîn û ji çerm tê çêkirin?', 'Zirna', 'Tembûr', 'Kemançe', 'Def', 'D', 'Def amûreke muzîkê ye ku ji çerm tê çêkirin û bi lêxistina wê ritm ji bo govendê tê dayîn.', 'Def amûreke muzîkê ye ku ji çerm tê çêkirin û bi lêxistina wê ritm ji bo govendê tê dayîn.', 'Def, deriden yapılan ve çalınarak halay için ritim sağlayan bir müzik aletidir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Daf', NULL, 'https://en.wikipedia.org/wiki/Daf', 'approved', 'Kurmancî', 1, now()),
('76b21777-ea92-53ec-99ae-1af55d324709', (select id from categories where name = 'Çand'), 'ku-kmr', 'Kîjan xwarina kurdî bi hevîrê savarê û goştê hûrkirî tê çêkirin?', 'Birinç', 'Kutilk', 'Şorbeya nîskê', 'Fasûlî', 'B', 'Kutilk bi hevîrê savarê û navika goştê hûrkirî tê çêkirin; li gorî herêman diguhere.', 'Kutilk bi hevîrê savarê û navika goştê hûrkirî tê çêkirin; li gorî herêman diguhere.', 'Kutilk, bulgur/irmik hamurundan kabuk ve kıymalı iç harçla yapılır. Yörelere göre dış hamuru ve iç harcı değişir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kubba', NULL, 'https://en.wikipedia.org/wiki/Kubba', 'approved', 'Kurmancî', 1, now()),
('d8230f1d-0dc7-5b50-9955-7bcf22cff741', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di çanda kurdî de, dema mêvanek tê malê, kîjan tişt bi gelemperî ji wî re tê pêşkêş kirin?', 'Çay û şekir', 'Qehwe û nan', 'Şerab û penîr', 'Hingiv û rûn', 'A', 'Di çanda kurdî de, mêvanperwerî gelek giring e û çay bi gelemperî ji mêvanan re tê pêşkêş kirin, carinan bi şekir û nanê taybet.', 'Di çanda kurdî de, mêvanperwerî gelek giring e û çay bi gelemperî ji mêvanan re tê pêşkêş kirin, carinan bi şekir û nanê taybet.', 'Kürt kültüründe misafirperverlik çok önemlidir ve misafirlere genellikle çay ikram edilir, bazen şeker ve özel ekmekle birlikte.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_culture', NULL, 'https://en.wikipedia.org/wiki/Kurdish_culture', 'approved', 'Kurmancî', 1, now()),
('49a19325-7b7e-5d11-be60-960d2ad1d223', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di çanda kurdî de, dema mêvanek tê, kîjan tişt bi gelemperî nayê kirin?', 'Xwarin tê amadekirin', 'Derî tê girtin', 'Çay tê vexwarin', 'Sohbet tê kirin', 'B', 'Di mêvanperweriya kurdî de, derî bi gelemperî ji bo mêvanan vekirî dimîne, ne girtî. Xwarin amadekirin, çay vexwarin û sohbet kirin adetên mêvanperweriyê ne.', 'Di mêvanperweriya kurdî de, derî bi gelemperî ji bo mêvanan vekirî dimîne, ne girtî. Xwarin amadekirin, çay vexwarin û sohbet kirin adetên mêvanperweriyê ne.', 'Kürt misafirperverliğinde, kapı misafirler için genellikle açık kalır, kapalı değil. Yemek hazırlamak, çay içmek ve sohbet etmek misafirperverlik adetleridir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_culture', NULL, 'https://en.wikipedia.org/wiki/Kurdish_culture', 'approved', 'Kurmancî', 1, now()),
('69a12675-3128-59f7-8c61-b8e09213d486', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di çanda kurdî de, dema pitikek tê dinyayê, kîjan tişt bi gelemperî tê kirin?', 'Şîna girî', 'Şahî û pîrozbahî', 'Koçberî', 'Rojîgirtin', 'B', 'Dema pitikek tê dinyayê, di çanda kurdî de şahî û pîrozbahî tê kirin. Ev kevneşopî nîşana kêfxweşiya malbatê ye û ji bo pîrozkirina jiyana nû tê lidarxistin.', 'Dema pitikek tê dinyayê, di çanda kurdî de şahî û pîrozbahî tê kirin. Ev kevneşopî nîşana kêfxweşiya malbatê ye û ji bo pîrozkirina jiyana nû tê lidarxistin.', 'Kürt kültüründe bir bebek dünyaya geldiğinde şenlik ve kutlama yapılır. Bu gelenek ailenin mutluluğunun bir göstergesidir ve yeni bir hayatı kutlamak için düzenlenir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_culture', NULL, 'https://en.wikipedia.org/wiki/Kurdish_culture', 'approved', 'Kurmancî', 1, now()),
('efadef75-7476-537f-8b44-a0e76204c138', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di çanda kurdî de, dema pitik tê dinyayê, kîjan kes bi gelemperî mizgîniyê dide malbatê?', 'Dayik', 'Pîrik', 'Bav', 'Xwişk', 'B', 'Di çanda kurdî de, pîrik bi gelemperî mizgîniyê dide malbatê. Ev yek ji ber ku pîrik di jidayikbûnê de amade ye û yekem kes e ku mizgîniyê dide.', 'Di çanda kurdî de, pîrik bi gelemperî mizgîniyê dide malbatê. Ev yek ji ber ku pîrik di jidayikbûnê de amade ye û yekem kes e ku mizgîniyê dide.', 'Kürt kültüründe ebe genellikle aileye müjdeyi verir. Bunun nedeni ebenin doğumda hazır bulunması ve müjdeyi veren ilk kişi olmasıdır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Kurdish_culture', NULL, 'https://en.wikipedia.org/wiki/Kurdish_culture', 'approved', 'Kurmancî', 1, now()),
('17cd20e2-cf9e-5e5c-887e-0403af75e3a8', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di zozanan de, ajal bi gelemperî çi dixwin?', 'Giya', 'Berû', 'Kakil', 'Keskesor', 'A', 'Zozan bi giyayên xwe yên dewlemend tên nasîn. Berû, kakil û keskesor ne xwarina sereke ya ajalan e.', 'Zozan bi giyayên xwe yên dewlemend tên nasîn. Berû, kakil û keskesor ne xwarina sereke ya ajalan e.', 'Yaylalar zengin otlarıyla bilinir. Meşe palamudu, çekirdek ve gökkuşağı hayvanların ana yemeği değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Mountain_meadow', NULL, 'https://en.wikipedia.org/wiki/Mountain_meadow', 'approved', 'Kurmancî', 1, now()),
('ddf32e99-f7c9-5526-8c96-304c0b657158', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di zivistanê de, koçer bi gelemperî li ku dimînin?', 'Li zozanan', 'Li deştan', 'Li çiyayan', 'Li bajaran', 'B', 'Zivistanê zozan sar e, ji ber vê yekê koçer li deştan dimînin. Zozan, çiya û bajar ne cihê zivistanê ne.', 'Zivistanê zozan sar e, ji ber vê yekê koçer li deştan dimînin. Zozan, çiya û bajar ne cihê zivistanê ne.', 'Kışın yaylalar soğuktur, bu yüzden göçerler ovalarda kalır. Yaylalar, dağlar ve şehirler kışlık yer değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Transhumance', NULL, 'https://en.wikipedia.org/wiki/Transhumance', 'approved', 'Kurmancî', 1, now()),
('d6906b0b-052d-5143-b532-4e2fbaa8a26c', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di havînê de, zozan bi gelemperî ji bo çi tên bikaranîn?', 'Ji bo çêrandinê', 'Ji bo avdanê', 'Ji bo xanî', 'Ji bo karxaneyê', 'A', 'Zozan havînê ji bo çêrandina ajalan tên bikaranîn. Avdan, xanî û karxane ne ji bo zozanan in.', 'Zozan havînê ji bo çêrandina ajalan tên bikaranîn. Avdan, xanî û karxane ne ji bo zozanan in.', 'Yaylalar yazın hayvanları otlatmak için kullanılır. Sulama, ev ve fabrika yaylalar için değildir.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Mountain_meadow', NULL, 'https://en.wikipedia.org/wiki/Mountain_meadow', 'approved', 'Kurmancî', 1, now()),
('0d60f58a-e650-5e23-81c3-7d7bef864ea6', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di Newrozê de, kîjan agir bi gelemperî tê vêxistin?', 'agirê tirsê', 'agirê mirinê', 'agirê pîroz', 'agirê xemê', 'C', 'Di Newrozê de agirê pîroz tê vêxistin ji ber ku Newroz cejna biharê ye û agir sembola paqijî û nûbûnê ye.', 'Di Newrozê de agirê pîroz tê vêxistin ji ber ku Newroz cejna biharê ye û agir sembola paqijî û nûbûnê ye.', 'Newroz''da kutsal ateş yakılır çünkü Newroz bahar bayramıdır ve ateş saflık ile yenilenmenin sembolüdür.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Nowruz', NULL, 'https://en.wikipedia.org/wiki/Nowruz', 'approved', 'Kurmancî', 1, now()),
('1795e616-8f19-5335-b797-7a902b743dff', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di cejna Qurbanê de, kîjan tişt bi gelemperî tê belavkirin?', 'xurma', 'nan', 'goşt', 'şîr', 'C', 'Di cejna Qurbanê de goşt tê belavkirin ji ber ku ew cejna qurbaniyê ye û goşt bi gelemperî ji bo feqîran tê belavkirin.', 'Di cejna Qurbanê de goşt tê belavkirin ji ber ku ew cejna qurbaniyê ye û goşt bi gelemperî ji bo feqîran tê belavkirin.', 'Kurban Bayramı''nda et dağıtılır çünkü o kurban bayramıdır ve et genellikle fakirlere dağıtılır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Eid_al-Adha', NULL, 'https://en.wikipedia.org/wiki/Eid_al-Adha', 'approved', 'Kurmancî', 1, now()),
('e3be2f68-7ee1-5b5f-9413-78af0d72b74f', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di cejna Qurbanê de, kîjan kes bi gelemperî qurbanî dike?', 'zarok', 'serokê malê', 'jin', 'mêvan', 'B', 'Di cejna Qurbanê de serokê malê qurbanî dike ji ber ku ew cejna qurbaniyê ye û qurbanî bi gelemperî ji aliyê serokê malê ve tê kirin.', 'Di cejna Qurbanê de serokê malê qurbanî dike ji ber ku ew cejna qurbaniyê ye û qurbanî bi gelemperî ji aliyê serokê malê ve tê kirin.', 'Kurban Bayramı''nda evin reisi kurban keser çünkü o kurban bayramıdır ve kurban genellikle evin reisi tarafından kesilir.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Eid_al-Adha', NULL, 'https://en.wikipedia.org/wiki/Eid_al-Adha', 'approved', 'Kurmancî', 1, now()),
('42b867cc-a577-5c7b-bab6-f278f00116f4', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di Newrozê de kîjan sê reng bi hev re tên bikaranîn?', 'Reş, spî û gewr', 'Şîn, mor û qehweyî', 'Sor, kesk û zer', 'Spî, şîn û pembe', 'C', 'Di pîrozbahiyên Newrozê de sor, kesk û zer bi hev re tên bikaranîn.', 'Di pîrozbahiyên Newrozê de sor, kesk û zer bi hev re tên bikaranîn.', 'Newroz kutlamalarında kırmızı, yeşil ve sarı birlikte kullanılır; tek bir "doğru renk" yoktur.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Nowruz', NULL, 'https://en.wikipedia.org/wiki/Nowruz', 'approved', 'Kurmancî', 1, now()),
('ffb4c042-11a5-5fdf-bb7b-fb941d392dac', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di cejna Remezanê de, kîjan tişt bi gelemperî tê dayîn?', 'goşt', 'zekata fitreyê', 'nan', 'şîr', 'B', 'Berî Cejna Remezanê zekata fitreyê tê dayîn; zekata giştî peywireke din a salane ye.', 'Berî Cejna Remezanê zekata fitreyê tê dayîn; zekata giştî peywireke din a salane ye.', 'Ramazan Bayramı öncesinde verilen sadaka fitredir (zakat al-fitr). Genel zekât ayrı ve yıllık bir yükümlülüktür.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Eid_al-Fitr', NULL, 'https://en.wikipedia.org/wiki/Eid_al-Fitr', 'approved', 'Kurmancî', 1, now()),
('f13b1460-6046-5031-a9f0-099c7647a7f1', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di Newrozê de, kîjan tişt bi gelemperî tê vêxistin?', 'agir', 'av', 'ax', 'hewa', 'A', 'Di Newrozê de agir tê vêxistin ji ber ku ew sembola paqijî û nûbûnê ye û bi gelemperî ji bo pîrozkirina cejnê tê bikaranîn.', 'Di Newrozê de agir tê vêxistin ji ber ku ew sembola paqijî û nûbûnê ye û bi gelemperî ji bo pîrozkirina cejnê tê bikaranîn.', 'Newroz''da ateş yakılır çünkü o saflığın ve yenilenmenin sembolüdür ve genellikle bayramı kutlamak için kullanılır.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Nowruz', NULL, 'https://en.wikipedia.org/wiki/Nowruz', 'approved', 'Kurmancî', 1, now()),
('26bbd63f-94c8-5a40-a400-0e2b75d6f1a4', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di "Mem û Zîn" de Zîn ji kê hez dike?', 'Zîn', 'Mem', 'Beko', 'Tacdîn', 'B', 'Mem û Zîn mesnewiyeke li ser evîna Mem û Zînê ye; Ehmedê Xanî di 1695an de nivîsand.', 'Mem û Zîn mesnewiyeke li ser evîna Mem û Zînê ye; Ehmedê Xanî di 1695an de nivîsand.', 'Mem û Zîn, Mem ile Zîn''in aşkı üzerine kurulu bir mesnevidir; Ehmedê Xanî 1695''te yazmıştır. Beko araya giren fesatçı, Tacdîn ise Mem''in dostudur.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Mem_and_Zin', NULL, 'https://en.wikipedia.org/wiki/Mem_and_Zin', 'approved', 'Kurmancî', 1, now()),
('b7542feb-d885-5dbe-8bf6-978d8d31aaf0', (select id from categories where name = 'Çand'), 'ku-kmr', 'Di çîroka "Mem û Zîn" de, evîn bi kîjan awayî bi dawî dibe?', 'Bi zewacê', 'Bi trajediyê', 'Bi hevberdanê', 'Bi koçberiyê', 'B', 'Di çîroka Mem û Zîn de, evîn bi trajediyê bi dawî dibe; Mem û Zîn ji ber çarenivîsa neyînî û xapandinên Beko dimirin.', 'Di çîroka Mem û Zîn de, evîn bi trajediyê bi dawî dibe; Mem û Zîn ji ber çarenivîsa neyînî û xapandinên Beko dimirin.', 'Mem ile Zîn hikayesinde aşk trajediyle sona erer; Mem ve Zîn, olumsuz kader ve Beko''nun hileleri yüzünden ölürler.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Mem_and_Zin', NULL, 'https://en.wikipedia.org/wiki/Mem_and_Zin', 'approved', 'Kurmancî', 1, now()),
('a81c29e8-77e5-5ea7-9241-8db514b02b38', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Di mûzîka Êzdiyan de rola "Qewl" û "Qewlvan" ji kilamên dengbêjiyê yên klasîk bi çi awayî cuda dibe?', 'Qewl tenê stranên şahiyan e û di govendê de bi def û zirneyê têne qîrîn', 'Qewl tenê helbestên nivîskî yên li ser evîndariya nûjen in', 'Qewl metnên pîroz ên dînî ne û bi amûrên def û şibabê bi awayekî ayînî tên xwendin', 'Qewl bi zimanê latînî tên xwendin û di nav gel de nayên zanîn', 'C', 'Qewl metnên dînî yên pîroz in û ji aliyê qewlvanan ve bi def û şibabê têne gotin.', 'Qewl metnên dînî yên pîroz in û ji aliyê qewlvanan ve bi def û şibabê têne gotin.', 'Qewl, Êzdî inancının kutsal dini ilahileridir ve ayinlerde def ve şibab (kaval) eşliğinde okunur.', 4, true, 'multiple_choice', NULL, 'https://www.iranicaonline.org/articles/qawl/', 'QAWL - Encyclopaedia Iranica', 'https://www.iranicaonline.org/articles/qawl/', 'approved', 'Kurmancî', 1, now()),
('806e22d9-2905-5e92-b853-390d1461ca27', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Di mûzîka kurdî de kîjan ji van taybetmendiyan nîşan dide ku sîstema makamî ji ya klasîk a rojavayî cuda ye?', 'Tenê bikaranîna pîvana 4/4an û nebûna tu cureyên guherîna deng', 'Nivîsandina hemû berheman tenê li ser notaya piyanoya klasîk', 'Bikaranîna dengên navber (koma/mîkrotonal) li ser teşeyên herêmî û melodiyên azad', 'Qedexebûna dengê mirov û tenê bikaranîna amûrên bîflûtê', 'C', 'Mûzîka kurdî xwedî perdeyên mîkrotonal e ku di sîstema rojavayî de nînin.', 'Mûzîka kurdî xwedî perdeyên mîkrotonal e ku di sîstema rojavayî de nînin.', 'Kürt müziğindeki ses dizileri koma (mikrotonal) aralıklar içerir ve Batı tampere sistemine tam oturmaz.', 5, true, 'multiple_choice', NULL, 'https://arxiv.org/abs/2602.20744', 'Voices of the Mountains: Deep Learning-Based Vocal Error Detection System for Kurdish Maqams', 'https://arxiv.org/abs/2602.20744', 'approved', 'Kurmancî', 1, now()),
('08c08f22-44cd-56fe-b4af-df3498050568', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Di Radyoya Êrîvanê de kîjan hunermend wekî amûrjenê "mey û bilûrê" tê naskirin, ne wekî dengbêj?', 'Karapêtê Xaço', 'Egîdê Cimo', 'Aram Tîgran', 'Şeroyê Biro', 'B', 'Egîdê Cimo ("Mîrê Bilûrê") bi dehan salan di Radyoya Êrîvanê de bilûr û mey lêxist. Karapêtê Xaço ne amûrjen, dengbêj bû.', 'Egîdê Cimo ("Mîrê Bilûrê") bi dehan salan di Radyoya Êrîvanê de bilûr û mey lêxist. Karapêtê Xaço ne amûrjen, dengbêj bû.', 'Egîdê Cimo ("Mîrê Bilûrê") Erivan Radyosu''nda onlarca yıl bilûr ve mey çaldı. Karapêtê Xaço ise çalgıcı değil, dengbêjdir.', 4, true, 'multiple_choice', NULL, 'https://bianet.org/yazi/mire-bilure-egide-cimo-205075', '"Mîrê Bilûrê": Egîdê Cimo', 'https://bianet.org/yazi/mire-bilure-egide-cimo-205075', 'approved', 'Kurmancî', 1, now()),
('b9d4795a-1b15-5715-a950-0662de83245c', (select id from categories where name = 'Muzîk'), 'ku-kmr', 'Taybetmendiya mûzîkal a sereke ya Aram Tîgran a ku di nava mûzîka kurdî de cihekî cuda dide wî çi ye?', 'Tenê gotina stranên bê amûr bi dengê bilind li serê çiyayan', 'Bikaranîna piyanoyê wekî tekane amûra di hemû stranên xwe de', 'Çêkirina tenê stranên marşî yên leşkerî bê melodiyên lîrîk', 'Stranbêjiya bi amûra ûdê û yekkirina çandên ermenî, kurdî û asûrî', 'D', 'Aram Tîgran bi ûda xwe ya taybet stranên kurdî bi ahengeke nerm got û pirek di navbera gelan de ava kir.', 'Aram Tîgran bi ûda xwe ya taybet stranên kurdî bi ahengeke nerm got û pirek di navbera gelan de ava kir.', 'Aram Tîgran ud çalarak söylediği yumuşak vokaliyle Kürtçe şarkılara farklı ve zengin bir makam boyutu kazandırmıştır.', 5, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Aram_Tigran', 'Aram Tigran', 'https://en.wikipedia.org/wiki/Aram_Tigran', 'approved', 'Kurmancî', 1, now()),
('0158623b-8ef5-5802-9c26-bc1a44a59176', (select id from categories where name = 'Sînema'), 'ku-kmr', 'Di fîlma "Umut" (1970) a "Yılmaz Güney" de, hêmana ku wê ji sînemaya Yeşilçamê ya serdema xwe cuda dike çi ye?', 'Tenê bikaranîna kamerayên rengîn û bandorên taybet ên teknolojîk', 'Kişandina hemû dîmenan li welatên Ewropayê bi lîstikvanên biyanî', 'Li şûna çîrokên melodramatîk ên xeyalî, realîzma civakî ya xizanî û bêçaretiyê nîşan dide', 'Çêkirina fîlmeke komedî ya xwerû ya ji bo şahiya malbatê', 'C', 'Umut destpêka sînemaya realîst a civakî ye ku derdê mirovê hejar bê maske nîşan dide.', 'Umut destpêka sînemaya realîst a civakî ye ku derdê mirovê hejar bê maske nîşan dide.', 'Umut filmi, Yeşilçam''ın pembe melodram kalıplarını kırarak Türkiye ve Ortadoğu sinemasında gerçekçi sinemanın mihenk taşı olmuştur.', 5, true, 'multiple_choice', NULL, 'https://dergipark.org.tr/tr/pub/inifedergi/article/1859670', 'Türk Sinemasında Politik Gerçekçiliğin Kurucu Bir Eşiği Olarak Umut (1970)', 'https://dergipark.org.tr/tr/pub/inifedergi/article/1859670', 'approved', 'Kurmancî', 1, now()),
('caf165d6-c796-54ba-95d7-143be38d4003', (select id from categories where name = 'Sînema'), 'ku-kmr', 'Fîlma "Yol" di sala 1982an de dema ku Xelata Palmiyeya Zêrîn a Cannesê wergirt, çima ji aliyê derhêneriyê ve bûyereke bêhempa bû?', 'Senaryo û derhêneriya wê di girtîgehê de ji aliyê Yılmaz Güney ve hate xêzkirin û bi rêya Şerif Gören hate kişandin', 'Fîlma yekem bû ku bi tevahî bi zimanê îngilîzî li Amerîkayê hate çêkirin', 'Tenê bi alîkariya mûzîkjenên operaya Parîsê hate amadekirin', 'Yekem fîlm bû ku hemû lîstikvanên wê xelatên şexsî yên Cannesê girtin', 'A', 'Yılmaz Güney ji girtîgehê fîlm bi hûrgilî bi rê ve bir û Şerif Gören li qadê fîlm kişand.', 'Yılmaz Güney ji girtîgehê fîlm bi hûrgilî bi rê ve bir û Şerif Gören li qadê fîlm kişand.', 'Yılmaz Güney İmralı cezaevinden sahne sahne talimat vererek Şerif Gören''e çektirmiş, kurgusunu İsviçre ve Fransa''da tamamlamıştır.', 4, true, 'multiple_choice', NULL, 'https://www.festival-cannes.com/en/2017/yol-the-full-version-in-cannes-classics-the-birth-of-the-palme-dor-1982/', 'Yol - The full version in Cannes Classics, the birth of the Palme d’or 1982', 'https://www.festival-cannes.com/en/2017/yol-the-full-version-in-cannes-classics-the-birth-of-the-palme-dor-1982/', 'approved', 'Kurmancî', 1, now()),
