('67ce14b0-c831-57f0-ba0e-5668e3161fac', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di bernamekirinê de, kîjan têgeh ji bo komkirina komek fermanan di bin navekî de tê bikaranîn?', 'Guherbar', 'Fonksiyon', 'Xelek', 'Şert', 'B', 'Fonksiyon (function) di bernamekirinê de ji bo komkirina komek fermanan di bin navekî de tê bikaranîn. Guherbar, xelek û şert jî têgehên din in lê ne ji bo komkirinê ne.', 'Fonksiyon (function) di bernamekirinê de ji bo komkirina komek fermanan di bin navekî de tê bikaranîn. Guherbar, xelek û şert jî têgehên din in lê ne ji bo komkirinê ne.', 'Fonksiyon, programlamada bir dizi komutu bir isim altında toplamak için kullanılır. Değişken, döngü ve koşul diğer terimlerdir ancak komutları gruplamak için kullanılmazlar.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Function_(computer_programming)', NULL, 'https://en.wikipedia.org/wiki/Function_(computer_programming)', 'approved', 'Kurmancî', 1, now()),
('a0db567f-17fe-5b7f-8c21-f38b61b22e4f', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di bernamekirinê de, kîjan têgeh ji bo hilanîna nirxekê ya rast an derew tê bikaranîn?', 'Guherbar', 'Xelek', 'Şert', 'Boolean', 'D', 'Boolean di bernamekirinê de ji bo hilanîna nirxekê ya rast an derew tê bikaranîn. Guherbar, xelek û şert jî têgehên din in lê ne ji bo hilanîna nirxên rast/derew in.', 'Boolean di bernamekirinê de ji bo hilanîna nirxekê ya rast an derew tê bikaranîn. Guherbar, xelek û şert jî têgehên din in lê ne ji bo hilanîna nirxên rast/derew in.', 'Boolean, programlamada doğru veya yanlış değerini saklamak için kullanılır. Değişken, döngü ve koşul diğer terimlerdir ancak doğru/yanlış değerlerini saklamak için kullanılmazlar.', 1, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Boolean_data_type', NULL, 'https://en.wikipedia.org/wiki/Boolean_data_type', 'approved', 'Kurmancî', 1, now()),
