('01ca8b1f-c076-5e74-9676-2a9f535bd6a1', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Kîjan teknolojî ji bo nasnameya dîjîtal a bikarhêner bi karanîna taybetmendiyên laşî tê bikaranîn?', 'Şîfre', 'OTP', 'Biyometrîk', 'Kilîta ewlehiyê', 'C', 'Biyometrîk taybetmendiyên laşî yên wekî şopa tiliyan an rûyê bikarhêner ji bo nasnameyê bikar tîne.', 'Biyometrîk taybetmendiyên laşî yên wekî şopa tiliyan an rûyê bikarhêner ji bo nasnameyê bikar tîne.', 'Biyometrik, kullanıcının parmak izi veya yüzü gibi fiziksel özelliklerini kimlik doğrulama için kullanır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Biometrics', NULL, 'https://en.wikipedia.org/wiki/Biometrics', 'approved', 'Kurmancî', 1, now()),
