('31a0a368-4f71-5cb4-ae19-2972107197e3', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Di şîfrekirinê de, kîjan têgeh ji bo daneyên ku hatine şîfrekirin tê bikaranîn?', 'Plaintext', 'Ciphertext', 'Cleartext', 'Hash', 'B', 'Ciphertext daneyên ku hatine şîfrekirin e; ew ji aliyê kesên nedestûrdar ve nayê xwendin.', 'Ciphertext daneyên ku hatine şîfrekirin e; ew ji aliyê kesên nedestûrdar ve nayê xwendin.', 'Ciphertext şifrelenmiş veridir; yetkisiz kişiler için okunamaz.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Ciphertext', NULL, 'https://en.wikipedia.org/wiki/Ciphertext', 'approved', 'Kurmancî', 1, now()),
('3edbb338-1bef-51ff-8015-12d7b5028aa2', (select id from categories where name = 'Teknolojî'), 'ku-kmr', 'Kîjan rêbaz ji bo piştrastkirina nasnameya bikarhêner bi du qonaxan tê bikaranîn?', 'OAuth 2.0', 'Kodê vegerandinê', 'Şîfreya tenê', '2FA', 'D', '2FA (Two-Factor Authentication) ji bo piştrastkirina nasnameyê du qonaxan bikar tîne, ewlekariyê zêde dike.', '2FA (Two-Factor Authentication) ji bo piştrastkirina nasnameyê du qonaxan bikar tîne, ewlekariyê zêde dike.', '2FA (İki Faktörlü Kimlik Doğrulama), kimlik doğrulamak için iki aşama kullanır, güvenliği artırır.', 2, true, 'multiple_choice', NULL, 'https://en.wikipedia.org/wiki/Multi-factor_authentication', NULL, 'https://en.wikipedia.org/wiki/Multi-factor_authentication', 'approved', 'Kurmancî', 1, now()),
